INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2317', 'dumbbell seated bent arm lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle. Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos flexionados en un ángulo de 90 grados. Manteniendo los codos flexionados, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/2317-JzQbv7J.jpg', 'videos/2317-JzQbv7J.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1730', 'dumbbell seated bent over alternate kickback', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with a dumbbell in each hand, palms facing inwards. Bend forward at the waist, keeping your back straight and parallel to the ground. Extend one arm straight back, keeping it close to your body, until your arm is fully extended. Pause for a moment, then slowly lower the dumbbell back to the starting position. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende un brazo recto hacia atrás, manteniéndolo cerca de tu cuerpo, hasta que el brazo esté completamente extendido. Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'shoulders', '["shoulders","back"]'::jsonb, 'triceps', 'images/1730-x0lwvfq.jpg', 'videos/1730-x0lwvfq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1737', 'dumbbell seated bent over triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand. Bend forward at the waist, keeping your back straight and your head up. Extend your arms straight back, keeping your elbows close to your head. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y la cabeza erguida. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca de la cabeza. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","back"]'::jsonb, 'triceps', 'images/1737-4ievMJ9.jpg', 'videos/1737-4ievMJ9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1677', 'dumbbell seated bicep curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up. Keep your back straight and your elbows close to your torso. Exhale and curl the dumbbells up towards your shoulders, contracting your biceps. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1677-xiA6lRr.jpg', 'videos/1677-xiA6lRr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0390', 'dumbbell seated biceps curl (on stability ball)', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing forward and your arms fully extended. Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0390-WgJnBH5.jpg', 'videos/0390-WgJnBH5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3547', 'dumbbell seated biceps curl to shoulder press', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in each hand with your palms facing forward and arms fully extended. Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders. Once your forearms are vertical, rotate your wrists so that your palms are facing forward. Press the dumbbells overhead until your arms are fully extended. Lower the dumbbells back down to the starting position by reversing the movement. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los codos cerca de tus costados, flexiona las mancuernas hacia los hombros. Una vez que tus antebrazos estén verticales, gira las muñecas de modo que las palmas queden hacia adelante. Presiona las mancuernas por encima de la cabeza hasta que los brazos estén completamente extendidos. Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'biceps', 'images/3547-OeL23VY.jpg', 'videos/3547-OeL23VY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1379', 'dumbbell seated calf raise', 'lower legs', 'lower legs', 'dumbbell', 'Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs. Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge. Hold onto the dumbbell for stability. Raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos. Coloca la punta de los pies sobre una superficie elevada, como un escalón o un bloque, con los talones colgando del borde. Sujétate de la mancuerna para mantener la estabilidad. Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1379-r29jP7S.jpg', 'videos/1379-r29jP7S.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0391', 'dumbbell seated curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward. Keep your back straight and your elbows close to your torso. Exhale and curl the dumbbells up towards your shoulders, contracting your biceps. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, con las palmas hacia adelante. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0391-TiaZTxx.jpg', 'videos/0391-TiaZTxx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0392', 'dumbbell seated front raise', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs. Keep your back straight and core engaged. Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas frente a ti, con las palmas hacia abajo, hasta que queden a la altura de los hombros. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","biceps"]'::jsonb, 'delts', 'images/0392-Ys97II0.jpg', 'videos/0392-Ys97II0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1678', 'dumbbell seated hammer curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos rectos hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1678-IGtBdNT.jpg', 'videos/1678-IGtBdNT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0393', 'dumbbell seated inner biceps curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up. Rest your upper arms on your thighs, allowing the dumbbells to hang down. Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya la parte superior de los brazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo. Manteniendo la parte superior de los brazos fija, flexiona las mancuernas hacia los hombros contrayendo los bíceps. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0393-KXyoEtA.jpg', 'videos/0393-KXyoEtA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0394', 'dumbbell seated kickback', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand. Bend your knees slightly and lean forward from your hips, keeping your back straight. Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Acerca la parte superior de los brazos a tus costados y mantén los codos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0394-en550rk.jpg', 'videos/0394-en550rk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0396', 'dumbbell seated lateral raise', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs. Keep your back straight and core engaged. Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","upper back"]'::jsonb, 'delts', 'images/0396-hxyTtWj.jpg', 'videos/0396-hxyTtWj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0395', 'dumbbell seated lateral raise v. 2', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs. Keep your back straight and core engaged. Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos. Mantén la espalda recta y el core activado. Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","triceps"]'::jsonb, 'delts', 'images/0395-hrrS0Ed.jpg', 'videos/0395-hrrS0Ed.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0397', 'dumbbell seated neutral wrist curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other. Rest your forearms on your thighs, allowing the dumbbells to hang down. Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas mirándose entre sí. Apoya los antebrazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo. Manteniendo las muñecas en posición neutra, flexiona las mancuernas hacia los hombros. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0397-uJmK7Z1.jpg', 'videos/0397-uJmK7Z1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1679', 'dumbbell seated one arm bicep curl on exercise ball with leg raised', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand with your palm facing up and your arm fully extended. Place your other hand on your hip for stability. Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary. Pause for a moment at the top of the movement, squeezing your bicep. Slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions. Switch arms and repeat the exercise.', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido. Coloca la otra mano en la cadera para mantener el equilibrio. Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo. Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de brazo y repite el ejercicio.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/1679-84sESNy.jpg', 'videos/1679-84sESNy.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0398', 'dumbbell seated one arm kickback', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand. Bend your torso forward at the waist, keeping your back straight and parallel to the ground. Extend your arm straight back, keeping your elbow close to your body. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano. Inclina el torso hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0398-VQ3sNCn.jpg', 'videos/0398-VQ3sNCn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0399', 'dumbbell seated one arm rotate', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh. Raise the dumbbell up to shoulder height, keeping your elbow close to your body. Rotate your forearm outward, away from your body, while keeping your upper arm stationary. Pause for a moment at the top, then slowly rotate your forearm back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Siéntate en un banco con la espalda recta y sujeta una mancuerna con una mano, apoyándola sobre el muslo. Sube la mancuerna hasta la altura del hombro, manteniendo el codo cerca de tu cuerpo. Gira el antebrazo hacia afuera, alejándolo de tu cuerpo, mientras mantienes fija la parte superior del brazo. Haz una pausa por un momento en la parte superior, luego gira lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'shoulders', '["shoulders","biceps"]'::jsonb, 'forearms', 'images/0399-7f2jsqP.jpg', 'videos/0399-7f2jsqP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0400', 'dumbbell seated one leg calf raise', 'lower legs', 'lower legs', 'dumbbell', 'Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh. Extend your left leg straight out in front of you, keeping your foot flexed. Place the ball of your right foot on an elevated surface, such as a step or weight plate. Using your calf muscles, raise your right heel as high as possible. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre el muslo derecho. Extiende la pierna izquierda recta hacia adelante, manteniendo el pie flexionado. Coloca la punta del pie derecho sobre una superficie elevada, como un escalón o un disco de peso. Usando los músculos de la pantorrilla, eleva el talón derecho lo más alto posible. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/0400-Ia7tumC.jpg', 'videos/0400-Ia7tumC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1380', 'dumbbell seated one leg calf raise - hammer grip', 'lower legs', 'lower legs', 'dumbbell', 'Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs. Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge. Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle. Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch to the other leg.', 'Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos. Coloca un pie sobre una superficie elevada, como un escalón o un bloque, con el talón colgando del borde. Sujeta la mancuerna con agarre neutro, es decir, con las palmas mirándose entre sí y los dedos envolviendo la barra. Manteniendo el core activado y la espalda recta, eleva lentamente el talón lo más alto posible empujando con la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1380-FxhcxUW.jpg', 'videos/1380-FxhcxUW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1381', 'dumbbell seated one leg calf raise - palm up', 'lower legs', 'lower legs', 'dumbbell', 'Sit on a bench or chair with your back straight and your feet flat on the ground. Hold a dumbbell in one hand and place it on top of your thigh, palm facing up. Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent. Raise your heel as high as possible by pushing through the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down. Repeat for the desired number of repetitions, then switch legs and repeat.', 'Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo. Sujeta una mancuerna con una mano y colócala sobre el muslo, con la palma hacia arriba. Levanta una pierna del suelo y extiéndela frente a ti, manteniendo la rodilla ligeramente flexionada. Eleva el talón lo más alto posible empujando con la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1381-VW88JNd.jpg', 'videos/1381-VW88JNd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0401', 'dumbbell seated palms up wrist curl', 'lower arms', 'lower arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your wrists upward, squeezing your forearms at the top of the movement. Pause for a moment, then lower your wrists back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento. Haz una pausa por un momento y luego baja las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'forearms', 'images/0401-2dImyQ8.jpg', 'videos/0401-2dImyQ8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0402', 'dumbbell seated preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a preacher curl bench with your feet flat on the floor. Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad. Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder. Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco scott con los pies apoyados en el suelo. Sujeta una mancuerna con una mano con agarre supino, apoyando la parte superior del brazo en la almohadilla del banco scott. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0402-7D5bgLT.jpg', 'videos/0402-7D5bgLT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0403', 'dumbbell seated revers grip concentration curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up. Rest your elbow on the inside of your thigh, just above the knee. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0403-lyKCLmK.jpg', 'videos/0403-lyKCLmK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1738', 'dumbbell seated reverse grip one arm overhead tricep extension', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell with an underhand grip and extend your arm straight up overhead. Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary. Pause for a moment, then extend your arm back up to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con agarre supino y extiende el brazo recto por encima de la cabeza. Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto. Haz una pausa por un momento, luego extiende el brazo de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1738-5fKX7wi.jpg', 'videos/1738-5fKX7wi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0405', 'dumbbell seated shoulder press', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with a dumbbell in each hand, resting on your thighs. Raise the dumbbells to shoulder height, palms facing forward. Press the dumbbells upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', 'Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos. Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0405-znQUdHY.jpg', 'videos/0405-znQUdHY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0404', 'dumbbell seated shoulder press (parallel grip)', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with a dumbbell in each hand, palms facing inward. Raise the dumbbells to shoulder height, elbows bent and palms facing forward. Press the dumbbells upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0404-f1jf47L.jpg', 'videos/0404-f1jf47L.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2188', 'dumbbell seated triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell with both hands and extend your arms straight up overhead. Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears. Pause for a moment, then straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza. Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Haz una pausa por un momento, luego endereza los brazos y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/2188-kont8Ut.jpg', 'videos/2188-kont8Ut.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0406', 'dumbbell shrug', 'back', 'back', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body. Keep your arms straight and let the dumbbells hang by your sides. Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders. Hold the contraction for a second, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Mantén los brazos rectos y deja que las mancuernas cuelguen a tus costados. Eleva los hombros lo más alto posible, como si intentaras tocarte las orejas con ellos. Mantén la contracción durante un segundo, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'traps', 'images/0406-NJzBsGJ.jpg', 'videos/0406-NJzBsGJ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0407', 'dumbbell side bend', 'waist', 'waist', 'dumbbell', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side. Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides and repeat.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano y dejando que cuelgue a tu costado. Manteniendo la espalda recta y el core activado, inclínate lentamente hacia el lado opuesto de la mancuerna, bajando el peso tanto como te sea posible con comodidad. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y repite.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0407-IpONWYv.jpg', 'videos/0407-IpONWYv.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0408', 'dumbbell side lying one hand raise', 'shoulders', 'shoulders', 'dumbbell', 'Lie on your side with your legs extended and your head supported by your arm. Hold a dumbbell in your top hand with your palm facing down. Keeping your arm straight, raise the dumbbell up to shoulder height. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo. Sujeta una mancuerna con la mano de arriba, con la palma hacia abajo. Manteniendo el brazo recto, sube la mancuerna hasta la altura del hombro. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0408-fTlkJop.jpg', 'videos/0408-fTlkJop.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3664', 'dumbbell side plank with rear fly', 'back', 'back', 'dumbbell', 'Start by lying on your side with your legs extended and stacked on top of each other. Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle. Hold a dumbbell in your top hand, with your arm extended straight down towards the ground. Engage your core and lift your hips off the ground, creating a straight line from your head to your heels. While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together. Lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca el antebrazo en el suelo, justo debajo del hombro, manteniendo el codo flexionado en un ángulo de 90 grados. Sujeta una mancuerna con la mano de arriba, con el brazo extendido recto hacia el suelo. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los talones. Manteniendo la posición de plancha lateral, levanta la mancuerna hacia el techo, apretando los omóplatos entre sí. Baja la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'shoulders', '["shoulders","core"]'::jsonb, 'upper back', 'images/3664-X6ytgYZ.jpg', 'videos/3664-X6ytgYZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3548', 'dumbbell single arm overhead carry', 'shoulders', 'shoulders', 'dumbbell', 'Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand. Raise the dumbbell overhead, fully extending your arm. Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead. Continue walking for the desired distance or time. Switch hands and repeat the exercise.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo. Activa el core y mantén la espalda recta mientras caminas hacia adelante, sosteniendo la mancuerna por encima de la cabeza. Continúa caminando durante la distancia o el tiempo deseado. Cambia de mano y repite el ejercicio.', 'traps', '["traps","core"]'::jsonb, 'delts', 'images/3548-mWBtgmb.jpg', 'videos/3548-mWBtgmb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0409', 'dumbbell single leg calf raise', 'lower legs', 'lower legs', 'dumbbell', 'Stand on the edge of a step or platform with your heels hanging off and your toes on the step. Hold a dumbbell in one hand and place your other hand on a wall or railing for support. Raise your heel as high as possible, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heel back down below the step. Repeat for the desired number of repetitions, then switch to the other leg.', 'Ponte de pie en el borde de un escalón o plataforma, con los talones colgando y la punta de los pies sobre el escalón. Sujeta una mancuerna con una mano y coloca la otra mano sobre una pared o barandilla para apoyarte. Eleva el talón lo más alto posible, levantando el cuerpo sobre la punta de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón por debajo del nivel del escalón. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', 'ankles', '["ankles"]'::jsonb, 'calves', 'images/0409-1kB3Wmk.jpg', 'videos/0409-1kB3Wmk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1757', 'dumbbell single leg deadlift', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet hip-width apart, holding a dumbbell in your right hand. Shift your weight onto your left leg and lift your right foot slightly off the ground. Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground. At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee. Lower the dumbbell until your torso and right leg are parallel to the ground. Pause for a moment, then engage your glutes and hamstrings to return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha. Traslada tu peso a la pierna izquierda y levanta el pie derecho ligeramente del suelo. Manteniendo la espalda recta, inclínate hacia adelante desde las caderas y baja la mancuerna hacia el suelo. Al mismo tiempo, extiende la pierna derecha recta hacia atrás, manteniendo una ligera flexión en la rodilla izquierda. Baja la mancuerna hasta que tu torso y tu pierna derecha queden paralelos al suelo. Haz una pausa por un momento, luego activa los glúteos y los isquiotibiales para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/1757-gKozT8X.jpg', 'videos/1757-gKozT8X.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2805', 'dumbbell single leg deadlift with stepbox support', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet hip-width apart, holding a dumbbell in your right hand. Place your left foot on a stepbox or elevated surface behind you. Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground. As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel. Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha. Coloca el pie izquierdo sobre un cajón de step o una superficie elevada detrás de ti. Manteniendo la espalda recta y el core activado, inclínate hacia adelante desde las caderas, bajando la mancuerna hacia el suelo. Mientras bajas la mancuerna, levanta al mismo tiempo la pierna izquierda detrás de ti, manteniendo una línea recta desde la cabeza hasta el talón. Baja la mancuerna hasta sentir un estiramiento en el isquiotibial derecho, luego vuelve a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/2805-daBmy1Y.jpg', 'videos/2805-daBmy1Y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0410', 'dumbbell single leg split squat', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step. Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground. Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso hacia adelante con un pie y coloca los pies de modo que el pie delantero quede plano en el suelo y el pie trasero quede elevado sobre un banco o escalón. Baja el cuerpo flexionando la rodilla y la cadera delanteras, manteniendo la rodilla trasera ligeramente flexionada y el talón trasero levantado del suelo. Continúa bajando hasta que el muslo delantero quede paralelo al suelo, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0410-qx4fgX7.jpg', 'videos/0410-qx4fgX7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0411', 'dumbbell single leg squat', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Extend one leg forward and keep it off the ground throughout the exercise. Bend your standing leg and lower your body down as if sitting back into a chair. Keep your chest up and your back straight. Pause for a moment at the bottom, then push through your heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Extiende una pierna hacia adelante y mantenla levantada del suelo durante todo el ejercicio. Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla. Mantén el pecho arriba y la espalda recta. Haz una pausa por un momento en la posición más baja, luego empuja con el talón para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0411-H6ybluc.jpg', 'videos/0411-H6ybluc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0413', 'dumbbell squat', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Manteniendo el pecho arriba y el core activado, baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0413-HsvHqgf.jpg', 'videos/0413-HsvHqgf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3560', 'dumbbell standing alternate hammer curl and press', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your body. Keep your elbows close to your torso and your back straight. Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Inhale and slowly lower the dumbbell back to the starting position. Repeat the curl with your left hand. After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead. Extend your arm fully and hold for a moment at the top. Inhale and slowly lower the dumbbell back to the starting position. Repeat the press with your left hand. Continue alternating between curls and presses for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y la espalda recta. Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el curl con la mano izquierda. Después de completar el curl con la mano izquierda, exhala y presiona la mancuerna de la mano derecha por encima de la cabeza. Extiende completamente el brazo y mantén la posición por un momento en la parte superior. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el press con la mano izquierda. Continúa alternando entre curls y press durante el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/3560-LeaZOIz.jpg', 'videos/3560-LeaZOIz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0414', 'dumbbell standing alternate overhead press', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward. Press one dumbbell overhead, fully extending your arm. Lower the dumbbell back to shoulder level. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante. Presiona una mancuerna por encima de la cabeza, extendiendo completamente el brazo. Baja la mancuerna de vuelta a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0414-bBi35y3.jpg', 'videos/0414-bBi35y3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0415', 'dumbbell standing alternate raise', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body. Keep your back straight and your core engaged. Raise one dumbbell to the side, keeping your arm straight and your palm facing down. Continue lifting until your arm is parallel to the ground. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat with the other arm. Alternate between arms for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo. Mantén la espalda recta y el core activado. Levanta una mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', 'traps', '["traps","forearms"]'::jsonb, 'delts', 'images/0415-SxHteRW.jpg', 'videos/0415-SxHteRW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1739', 'dumbbell standing alternating tricep kickback', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight back, keeping your elbows close to your body. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat with the other arm, alternating sides with each repetition.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite con el otro brazo, alternando lados en cada repetición.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1739-Gi2BXfK.jpg', 'videos/1739-Gi2BXfK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2143', 'dumbbell standing around world', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Extend your arms straight out to the sides at shoulder height, palms facing down. Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead. Continue the circular motion, bringing the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Extiende los brazos rectos hacia los lados a la altura de los hombros, con las palmas hacia abajo. Manteniendo los brazos rectos, gira lentamente los brazos en un movimiento circular, llevando las mancuernas frente al cuerpo y luego por encima de la cabeza. Continúa el movimiento circular, bajando las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","forearms"]'::jsonb, 'delts', 'images/2143-RSOsp5d.jpg', 'videos/2143-RSOsp5d.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1740', 'dumbbell standing bent over one arm triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand. Bend forward at the waist, keeping your back straight and parallel to the ground. Extend your arm straight back, keeping your elbow close to your body. Slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo. Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'shoulders', '["shoulders","back"]'::jsonb, 'triceps', 'images/1740-CJwa0vD.jpg', 'videos/1740-CJwa0vD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1741', 'dumbbell standing bent over two arm triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend forward at the waist, keeping your back straight and your knees slightly bent. Extend your arms straight back, keeping your elbows close to your body. Slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo. Baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","back"]'::jsonb, 'triceps', 'images/1741-3T12T87.jpg', 'videos/1741-3T12T87.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0416', 'dumbbell standing biceps curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0416-3s4NnTh.jpg', 'videos/0416-3s4NnTh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0417', 'dumbbell standing calf raise', 'lower legs', 'lower legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Raise your heels off the ground as high as possible, using your calves. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'ankles', '["ankles"]'::jsonb, 'calves', 'images/0417-dPmaUaU.jpg', 'videos/0417-dPmaUaU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0418', 'dumbbell standing concentration curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards. Place your opposite hand on your thigh for support. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano, con el brazo completamente extendido y la palma hacia adentro. Apoya la otra mano sobre el muslo para mayor estabilidad. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0418-7inpWch.jpg', 'videos/0418-7inpWch.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0419', 'dumbbell standing front raise above head', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keep your arms straight and lift the dumbbells in front of you, raising them above your head. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Mantén los brazos rectos y levanta las mancuernas frente a ti, elevándolas por encima de la cabeza. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","biceps"]'::jsonb, 'delts', 'images/0419-laVRfDf.jpg', 'videos/0419-laVRfDf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2321', 'dumbbell standing inner biceps curl v. 2', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your torso. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. While holding your upper arms stationary, curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Slowly begin to bring the dumbbells back to the starting position as your breathe in. Repeat for the recommended amount of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Manteniendo fija la parte superior de los brazos, flexiona los pesos mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Comienza a llevar lentamente las mancuernas de vuelta a la posición inicial mientras inhalas. Repite el número de repeticiones recomendado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2321-vKilzz3.jpg', 'videos/2321-vKilzz3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0420', 'dumbbell standing kickback', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms straight back, squeezing your triceps at the top of the movement. Pause for a moment, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0420-UmpPAAe.jpg', 'videos/0420-UmpPAAe.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0421', 'dumbbell standing one arm concentration curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up. Place your free hand on your thigh for support. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps. Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia arriba. Coloca la mano libre sobre el muslo para apoyarte. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0421-8fgqP5a.jpg', 'videos/0421-8fgqP5a.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0422', 'dumbbell standing one arm curl (over incline bench)', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward. Place your other hand on an incline bench for support. Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps. Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia adelante. Coloca la otra mano sobre un banco inclinado para apoyarte. Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0422-BIb1tGo.jpg', 'videos/0422-BIb1tGo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1680', 'dumbbell standing one arm curl over incline bench', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand. Place your other hand on an incline bench for support. Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Coloca la otra mano sobre un banco inclinado para apoyarte. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1680-EmlJR2y.jpg', 'videos/1680-EmlJR2y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0423', 'dumbbell standing one arm extension', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand. Raise the dumbbell overhead, fully extending your arm. Keep your upper arm close to your head and perpendicular to the ground. Slowly lower the dumbbell behind your head, bending your elbow. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo. Mantén la parte superior del brazo cerca de la cabeza y perpendicular al suelo. Baja lentamente la mancuerna detrás de la cabeza, flexionando el codo. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0423-BCUR88E.jpg', 'videos/0423-BCUR88E.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0424', 'dumbbell standing one arm palm in press', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards. Engage your core and keep your back straight. Press the dumbbell upwards until your arm is fully extended. Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano a la altura del hombro, con la palma hacia adentro. Activa el core y mantén la espalda recta. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0424-ocYc6Db.jpg', 'videos/0424-ocYc6Db.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0425', 'dumbbell standing one arm reverse curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip. Keep your arm fully extended and close to your body, with your palm facing down. Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary. Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano con agarre prono. Mantén el brazo completamente extendido y cerca del cuerpo, con la palma hacia abajo. Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0425-DU5Kkj2.jpg', 'videos/0425-DU5Kkj2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0426', 'dumbbell standing overhead press', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward. Press the dumbbells upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0426-A6wtbuL.jpg', 'videos/0426-A6wtbuL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0427', 'dumbbell standing palms in press', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards. Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adentro. Manteniendo el core activado y la espalda recta, presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/0427-UilDHSs.jpg', 'videos/0427-UilDHSs.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0428', 'dumbbell standing preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Apoya la parte posterior de la parte superior de los brazos contra el banco scott o un banco inclinado, con los codos ligeramente flexionados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0428-hq2hyDH.jpg', 'videos/0428-hq2hyDH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0429', 'dumbbell standing reverse curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano, con las palmas hacia tu cuerpo. Manteniendo fija la parte superior de los brazos, exhala y flexiona los pesos mientras contraes los bíceps. Continúa subiendo los pesos hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0429-0IgNjSM.jpg', 'videos/0429-0IgNjSM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0430', 'dumbbell standing triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand. Raise the dumbbell overhead, keeping your arm straight. Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary. Extend your arm back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, manteniendo el brazo recto. Flexiona el codo y baja la mancuerna detrás de la cabeza, manteniendo fija la parte superior del brazo. Extiende el brazo de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0430-PdmaD0N.jpg', 'videos/0430-PdmaD0N.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2293', 'dumbbell standing zottman preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing forward. Place your upper arms against the preacher bench and keep your elbows slightly bent. Curl the dumbbells up towards your shoulders while keeping your upper arms stationary. At the top of the movement, rotate your wrists so that your palms are facing downward. Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Apoya la parte superior de los brazos contra el banco scott y mantén los codos ligeramente flexionados. Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos. En la parte superior del movimiento, gira las muñecas de modo que las palmas queden hacia abajo. Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2293-P2nRiUa.jpg', 'videos/2293-P2nRiUa.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1684', 'dumbbell step up single leg balance with bicep curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand in front of a step or platform with a dumbbell in each hand, palms facing your body. Place your right foot on the step, ensuring your entire foot is in contact with the surface. Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest. At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders. Lower the dumbbells back down and simultaneously lower your left foot back to the ground. Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté en contacto con la superficie. Activa el core y empuja con el talón derecho para subir el cuerpo sobre el escalón, llevando la rodilla izquierda hacia el pecho. En la parte superior del movimiento, realiza un curl de bíceps flexionando los codos y llevando las mancuernas hacia los hombros. Baja las mancuernas y, al mismo tiempo, baja el pie izquierdo de vuelta al suelo. Repite el movimiento del lado contrario, subiendo con el pie izquierdo y flexionando las mancuernas. Continúa alternando lados durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","glutes","hamstrings"]'::jsonb, 'biceps', 'images/1684-76vfTdU.jpg', 'videos/1684-76vfTdU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0431', 'dumbbell step-up', 'upper legs', 'upper legs', 'dumbbell', 'Stand in front of a bench or step with a dumbbell in each hand, palms facing your body. Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface. Push through your right heel and lift your body up onto the bench or step, straightening your right leg. Bring your left foot up onto the bench or step, standing fully upright. Step back down with your left foot, followed by your right foot, returning to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Empuja con el talón derecho y sube el cuerpo sobre el banco o escalón, enderezando la pierna derecha. Sube el pie izquierdo hasta el banco o escalón, quedando completamente erguido. Baja con el pie izquierdo, seguido del pie derecho, volviendo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0431-aXtJhlg.jpg', 'videos/0431-aXtJhlg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2796', 'dumbbell step-up lunge', 'upper legs', 'upper legs', 'dumbbell', 'Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides. Place your right foot on the step, ensuring your entire foot is on the surface. Push through your right heel and lift your body up onto the step, bringing your left foot up as well. Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step. Repeat the movement, alternating which foot you step up with each time. Continue for the desired number of repetitions.', 'Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tus costados. Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté sobre la superficie. Empuja con el talón derecho y sube el cuerpo sobre el escalón, llevando también el pie izquierdo hacia arriba. Una vez que ambos pies estén sobre el escalón, baja el pie izquierdo de vuelta a la posición inicial, manteniendo el pie derecho sobre el escalón. Repite el movimiento, alternando el pie con el que subes cada vez. Continúa durante el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/2796-gFyFj9z.jpg', 'videos/2796-gFyFj9z.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2812', 'dumbbell step-up split squat', 'upper legs', 'upper legs', 'dumbbell', 'Stand in front of a bench or step with a dumbbell in each hand, palms facing your body. Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface. Step up onto the bench or step with your right foot, pushing through your heel to lift your body up. As you step up, simultaneously lift your left knee towards your chest. Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step. Repeat the movement with your left foot on the bench or step. Continue alternating between your right and left foot for the desired number of repetitions.', 'Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Sube al banco o escalón con el pie derecho, empujando con el talón para levantar el cuerpo. Mientras subes, levanta al mismo tiempo la rodilla izquierda hacia el pecho. Haz una pausa en la parte superior del movimiento, luego baja lentamente el pie izquierdo de vuelta al suelo mientras mantienes el pie derecho sobre el banco o escalón. Repite el movimiento con el pie izquierdo sobre el banco o escalón. Continúa alternando entre el pie derecho y el izquierdo durante el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/2812-QjE2DcA.jpg', 'videos/2812-QjE2DcA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0432', 'dumbbell stiff leg deadlift', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees. Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo una ligera flexión en las rodillas. Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego aprieta los glúteos y empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0432-5eLRITT.jpg', 'videos/0432-5eLRITT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0433', 'dumbbell straight arm pullover', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with your head at one end and your feet planted firmly on the ground. Hold a dumbbell with both hands and extend your arms straight above your chest. Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion. Pause for a moment, then raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza con un movimiento en forma de arco. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'latissimus dorsi', '["latissimus dorsi","triceps"]'::jsonb, 'pectorals', 'images/0433-i8BdLTK.jpg', 'videos/0433-i8BdLTK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0434', 'dumbbell straight leg deadlift', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward. Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent. Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que el torso se incline hacia adelante. Continúa bajando las mancuernas hasta sentir un estiramiento en los isquiotibiales, manteniendo las rodillas ligeramente flexionadas. Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0434-oom75KC.jpg', 'videos/0434-oom75KC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2808', 'dumbbell sumo pull through', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet wider than shoulder-width apart, toes pointed outwards. Hold a dumbbell with both hands in front of your body, arms extended. Bend your knees and lower your hips down into a squat position, keeping your back straight. Lower the dumbbell down between your legs, keeping your arms straight. Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body. Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies más separados que la altura de los hombros, con las puntas de los pies hacia afuera. Sujeta una mancuerna con ambas manos frente a tu cuerpo, con los brazos extendidos. Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta. Baja la mancuerna entre las piernas, manteniendo los brazos rectos. Empuja con los talones y extiende las caderas hacia adelante, llevando la mancuerna hacia arriba y frente a tu cuerpo. Aprieta los glúteos en la parte superior del movimiento, luego baja la mancuerna de vuelta entre las piernas. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","core"]'::jsonb, 'glutes', 'images/2808-BmrwWzo.jpg', 'videos/2808-BmrwWzo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2803', 'dumbbell supported squat', 'upper legs', 'upper legs', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Manteniendo el pecho arriba y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/2803-r5DgrW9.jpg', 'videos/2803-r5DgrW9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0436', 'dumbbell tate press', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a flat bench with a dumbbell in each hand, palms facing each other. Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you. Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height. Rotate your wrists back to the starting position and repeat for the desired number of repetitions.', 'Siéntate en un banco plano con una mancuerna en cada mano, con las palmas mirándose entre sí. Sube las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia afuera. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos, luego bájalas de vuelta a la altura de los hombros. Gira las muñecas de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0436-s5PdDyY.jpg', 'videos/0436-s5PdDyY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1742', 'dumbbell tricep kickback with stork stance', 'upper arms', 'upper arms', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in your right hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Bring your right elbow up to your side, keeping it bent at a 90-degree angle. Extend your right arm straight back, squeezing your triceps. Pause for a moment, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados. Extiende el brazo derecho recto hacia atrás, apretando el tríceps. Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1742-wOLmCXc.jpg', 'videos/1742-wOLmCXc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1743', 'dumbbell twisting bench press', 'upper arms', 'upper arms', 'dumbbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Hold a dumbbell in each hand with an overhand grip, palms facing away from you. Extend your arms straight up over your chest, keeping a slight bend in your elbows. Lower the dumbbells down towards your chest, keeping your elbows close to your body. As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement. Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position. As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta una mancuerna en cada mano con agarre prono, con las palmas alejadas de ti. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Baja las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo. Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden hacia ti en la parte más baja del movimiento. Haz una pausa por un momento en la parte más baja, luego invierte el movimiento presionando las mancuernas de vuelta hacia arriba, hasta la posición inicial. Mientras presionas las mancuernas hacia arriba, gira las muñecas de vuelta a la posición inicial con las palmas alejadas de ti. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1743-z6TAHoT.jpg', 'videos/1743-z6TAHoT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0437', 'dumbbell upright row', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Let the dumbbells hang in front of your thighs, with your arms fully extended. Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos. Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","biceps"]'::jsonb, 'delts', 'images/0437-ainizkb.jpg', 'videos/0437-ainizkb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1765', 'dumbbell upright row (back pov)', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body. Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows. Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos y las palmas hacia tu cuerpo. Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos. Continúa subiendo hasta que las mancuernas estén a la altura de los hombros, con los codos apuntando hacia los lados. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","biceps"]'::jsonb, 'delts', 'images/1765-Iptlv6x.jpg', 'videos/1765-Iptlv6x.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0864', 'dumbbell upright shoulder external rotation', 'shoulders', 'shoulders', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body. Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent. Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position. Pause for a moment at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo los codos ligeramente flexionados. Gira los brazos hacia afuera, llevando las mancuernas hacia la cabeza mientras mantienes los codos en la misma posición. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'rotator cuff', '["rotator cuff","trapezius"]'::jsonb, 'delts', 'images/0864-x306lCW.jpg', 'videos/0864-x306lCW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('5201', 'dumbbell waiter biceps curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing forward. Keep your upper arms close to your body and your elbows tucked in. Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight. Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Mantén la parte superior de los brazos cerca del cuerpo y los codos pegados. Flexiona lentamente las mancuernas hacia los hombros, manteniendo las muñecas rectas. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/5201-KOpzGBL.jpg', 'videos/5201-KOpzGBL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0438', 'dumbbell w-press', 'shoulders', 'shoulders', 'dumbbell', 'Sit on a bench with a dumbbell in each hand, palms facing forward. Raise the dumbbells to shoulder height, elbows bent and palms facing forward. Press the dumbbells upward until your arms are fully extended overhead. Lower the dumbbells back to shoulder height. Repeat for the desired number of repetitions.', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante. Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Baja las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/0438-vmwLyCg.jpg', 'videos/0438-vmwLyCg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0439', 'dumbbell zottman curl', 'upper arms', 'upper arms', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your body. Keep your elbows close to your torso and rotate your palms to face forward. Curl the dumbbells up to your shoulders while keeping your upper arms stationary. At the top of the movement, rotate your wrists so that your palms are facing away from your body. Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body. Repeat for the desired number of repetitions.', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y gira las palmas para que queden hacia adelante. Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos. En la parte superior del movimiento, gira las muñecas de modo que las palmas queden alejadas de tu cuerpo. Baja lentamente las mancuernas de vuelta a la posición inicial, girando las palmas de nuevo hacia tu cuerpo. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0439-kXaIn5A.jpg', 'videos/0439-kXaIn5A.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2294', 'dumbbell zottman preacher curl', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad. Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up. At the top of the curl, rotate your wrists so that your palms are facing down. Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so. Repeat for the desired number of repetitions.', 'Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba y los codos apoyados en la almohadilla. Flexiona las mancuernas hacia los hombros, manteniendo fija la parte superior de los brazos y las palmas hacia arriba. En la parte superior del curl, gira las muñecas de modo que las palmas queden hacia abajo. Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original mientras lo haces. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2294-y5U5B9Y.jpg', 'videos/2294-y5U5B9Y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2189', 'dumbbells seated triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a dumbbell in both hands with an overhand grip, and raise it above your head. Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears. Extend your arms and raise the dumbbell back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos con agarre prono y levántala por encima de la cabeza. Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Extiende los brazos y sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/2189-FQXdXzY.jpg', 'videos/2189-FQXdXzY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1167', 'dynamic chest stretch (male)', 'chest', 'chest', 'body weight', 'Stand tall with your feet shoulder-width apart. Extend your arms straight out to the sides, parallel to the ground. Slowly bring your arms forward, crossing them in front of your body. Feel the stretch in your chest muscles. Hold the stretch for 10-30 seconds. Return to the starting position and repeat for the desired number of repetitions.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos hacia los lados, paralelos al suelo. Lleva lentamente los brazos hacia adelante, cruzándolos frente al cuerpo. Siente el estiramiento en los músculos del pecho. Mantén el estiramiento durante 10-30 segundos. Vuelve a la posición inicial y repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1167-3uj0Ozg.jpg', 'videos/1167-3uj0Ozg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3287', 'elbow dips', 'upper arms', 'upper arms', 'body weight', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips. Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas. Desliza las caderas hacia adelante, fuera del banco, y estira las piernas, manteniendo los talones en el suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/3287-LkoAWAE.jpg', 'videos/3287-LkoAWAE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1772', 'elbow lift - reverse push-up', 'back', 'back', 'body weight', 'Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders. Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides. Pause at the top for a moment, squeezing your upper back muscles. Slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza tumbado boca abajo en el suelo con las piernas extendidas y las manos colocadas justo debajo de los hombros. Activa el core y presiona con las palmas para levantar la parte superior del cuerpo del suelo, manteniendo los codos cerca de los costados. Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda alta. Baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'upper back', 'images/1772-wbUYILZ.jpg', 'videos/1772-wbUYILZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0443', 'elbow-to-knee', 'waist', 'waist', 'body weight', 'Start by lying flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee. At the same time, bring your left knee towards your right elbow, creating a twisting motion. Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position. Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow. Continue alternating sides for the desired number of repetitions.', 'Comienza tumbado boca arriba con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda. Al mismo tiempo, lleva la rodilla izquierda hacia el codo derecho, creando un movimiento de torsión. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo y extiende las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y la rodilla derecha hacia el codo izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0443-jvp6DiD.jpg', 'videos/0443-jvp6DiD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3292', 'elevator', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart and your knees slightly bent. Place your hands on your hips or cross them in front of your chest. Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground. Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Coloca las manos sobre las caderas o crúzalas frente al pecho. Manteniendo la espalda recta, inclínate lentamente hacia adelante desde la cintura, bajando la parte superior del cuerpo hacia el suelo. Haz una pausa por un momento en la posición más baja, luego sube lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","trapezius"]'::jsonb, 'upper back', 'images/3292-zYmNaoY.jpg', 'videos/3292-zYmNaoY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1332', 'exercise ball alternating arm ups', 'back', 'back', 'stability ball', 'Sit on the stability ball with your feet flat on the ground and your back straight. Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides. Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent. Pause for a moment at the top, then slowly lower your arm back down to the starting position. Repeat the movement with the other arm. Continue alternating arms for the desired number of repetitions.', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adentro y los brazos extendidos hacia abajo a los lados. Activa el core y levanta lentamente un brazo hacia el hombro, manteniendo el codo ligeramente flexionado. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el movimiento con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'shoulders', '["shoulders","core"]'::jsonb, 'lats', 'images/1332-EyLrNC2.jpg', 'videos/1332-EyLrNC2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1333', 'exercise ball back extension with arms extended', 'back', 'back', 'stability ball', 'Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability. Extend your arms straight out in front of you, with your palms facing down. Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Extiende los brazos rectos hacia adelante, con las palmas hacia abajo. Activa el core y levanta lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta y el cuello alineado con la columna. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/1333-PERjVm8.jpg', 'videos/1333-PERjVm8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1334', 'exercise ball back extension with hands behind head', 'back', 'back', 'stability ball', 'Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball. Position your feet against a wall or other stable surface for support. Cross your arms behind your head, with your hands touching the back of your head. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips. Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él con las caderas apoyadas en el balón. Coloca los pies contra una pared u otra superficie estable para apoyarte. Cruza los brazos detrás de la cabeza, con las manos tocando la parte de atrás de la cabeza. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta las caderas. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/1334-o1HGDSq.jpg', 'videos/1334-o1HGDSq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1335', 'exercise ball back extension with knees off ground', 'back', 'back', 'stability ball', 'Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability. Position your hands behind your head or crossed over your chest. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/1335-WME869U.jpg', 'videos/1335-WME869U.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1336', 'exercise ball back extension with rotation', 'back', 'back', 'stability ball', 'Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground. Place your hands behind your head or cross them over your chest. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels. Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable. Return to the center and repeat the rotation to the other side. Lower your upper body back down to the starting position and repeat for the desired number of repetitions.', 'Comienza tumbado boca abajo sobre el balón de estabilidad, con las caderas apoyadas en el balón y los pies firmemente apoyados en el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables. Vuelve al centro y repite el giro hacia el otro lado. Baja la parte superior del cuerpo de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/1336-WVD66ff.jpg', 'videos/1336-WVD66ff.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1744', 'exercise ball dip', 'upper arms', 'upper arms', 'stability ball', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Place your hands on the ball beside your hips, fingers pointing forward. Engage your triceps and push through your hands to lift your body off the ball, straightening your arms. Lower your body back down by bending your elbows, keeping them close to your sides. Repeat for the desired number of repetitions.', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Coloca las manos sobre el balón junto a las caderas, con los dedos apuntando hacia adelante. Activa el tríceps y empuja con las manos para levantar el cuerpo del balón, enderezando los brazos. Baja el cuerpo flexionando los codos, manteniéndolos cerca de los costados. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1744-kprile3.jpg', 'videos/1744-kprile3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1559', 'exercise ball hip flexor stretch', 'upper legs', 'upper legs', 'stability ball', 'Place the stability ball on the ground and kneel in front of it. Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle. Extend your left leg behind you, keeping it straight. Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor. Hold the stretch for 20-30 seconds, then switch sides and repeat.', 'Coloca el balón de estabilidad en el suelo y arrodíllate frente a él. Coloca el pie derecho sobre el balón de estabilidad, con la rodilla flexionada en un ángulo de 90 grados. Extiende la pierna izquierda hacia atrás, manteniéndola recta. Inclínate hacia adelante, empujando las caderas hacia el balón de estabilidad, hasta sentir un estiramiento en el flexor de la cadera derecha. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', 'quadriceps', '["quadriceps","hamstrings"]'::jsonb, 'glutes', 'images/1559-2LQkNPW.jpg', 'videos/1559-2LQkNPW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1338', 'exercise ball hug', 'back', 'back', 'stability ball', 'Sit on the stability ball with your feet flat on the ground and your back straight. Hold the stability ball with both hands, hugging it close to your chest. Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground. Continue leaning back until you feel a stretch in your back muscles. Hold the position for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta. Sujeta el balón de estabilidad con ambas manos, abrazándolo cerca del pecho. Activa los músculos del core y reclínate lentamente hacia atrás, manteniendo la espalda recta y los pies apoyados en el suelo. Continúa reclinándote hacia atrás hasta sentir un estiramiento en los músculos de la espalda. Mantén la posición durante unos segundos, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest"]'::jsonb, 'spine', 'images/1338-d7z1Y7V.jpg', 'videos/1338-d7z1Y7V.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1339', 'exercise ball lat stretch', 'back', 'back', 'stability ball', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand and extend your arm straight up overhead. Slowly lean to the opposite side, feeling a stretch in your lat muscle. Hold the stretch for 20-30 seconds, then return to the starting position. Repeat on the other side.', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sujeta una mancuerna con una mano y extiende el brazo recto por encima de la cabeza. Inclínate lentamente hacia el lado opuesto, sintiendo un estiramiento en el músculo dorsal. Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial. Repite del otro lado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'lats', 'images/1339-sM84pE4.jpg', 'videos/1339-sM84pE4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1341', 'exercise ball lower back stretch (pyramid)', 'back', 'back', 'stability ball', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball. Place your hands behind your head or cross them over your chest. Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball. Hold the stretch for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Camina lentamente hacia adelante con los pies, haciendo rodar el balón por tu espalda hasta que tu zona lumbar quede apoyada sobre el balón. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, permitiendo que tu zona lumbar se estire sobre el balón. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'lats', 'images/1341-yU7w7CA.jpg', 'videos/1341-yU7w7CA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1342', 'exercise ball lying side lat stretch', 'back', 'back', 'stability ball', 'Lie on your side with your legs extended and your head supported by the stability ball. Place your top arm on the ball for stability. Reach your top arm overhead and allow your torso to rotate slightly. Feel the stretch in your lat muscles on the side of your body. Hold the stretch for 20-30 seconds, then switch sides and repeat.', 'Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el balón de estabilidad. Coloca el brazo de arriba sobre el balón para mantener la estabilidad. Extiende el brazo de arriba por encima de la cabeza y permite que tu torso gire ligeramente. Siente el estiramiento en los músculos dorsales del costado de tu cuerpo. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'lats', 'images/1342-rTbyBYV.jpg', 'videos/1342-rTbyBYV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1382', 'exercise ball on the wall calf raise', 'lower legs', 'lower legs', 'dumbbell', 'Stand with your back against a wall and place an exercise ball between your lower back and the wall. Position your feet shoulder-width apart, with your toes pointing forward. Hold a dumbbell in each hand, with your arms extended by your sides. Raise your heels off the ground, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared. Coloca los pies separados a la altura de los hombros, con la punta de los pies hacia adelante. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados. Levanta los talones del suelo, llevando el peso de tu cuerpo hacia la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'calves', 'images/1382-xo6sENf.jpg', 'videos/1382-xo6sENf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3241', 'exercise ball on the wall calf raise (tennis ball between ankles)', 'lower legs', 'lower legs', 'dumbbell', 'Stand facing a wall with your feet shoulder-width apart. Place an exercise ball between the wall and your lower back. Hold a dumbbell in each hand, with your arms extended by your sides. Place a tennis ball between your ankles. Raise your heels off the ground, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una pared con los pies separados a la altura de los hombros. Coloca un balón de ejercicio entre la pared y tu zona lumbar. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados. Coloca una pelota de tenis entre los tobillos. Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'calves', 'images/3241-FY3UdNT.jpg', 'videos/3241-FY3UdNT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3240', 'exercise ball on the wall calf raise (tennis ball between knees)', 'lower legs', 'lower legs', 'dumbbell', 'Stand with your back against a wall and place an exercise ball between your lower back and the wall. Position your feet shoulder-width apart and slightly in front of you. Hold a dumbbell in each hand, with your arms extended by your sides. Place a tennis ball between your knees. Raise your heels off the ground, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared. Coloca los pies separados a la altura de los hombros y ligeramente por delante de ti. Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados. Coloca una pelota de tenis entre las rodillas. Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings"]'::jsonb, 'calves', 'images/3240-j74M6Zn.jpg', 'videos/3240-j74M6Zn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1416', 'exercise ball one leg prone lower body rotation', 'upper legs', 'upper legs', 'stability ball', 'Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you. Place your hands on the ground in front of you for support. Engage your glutes and core muscles to stabilize your body. Slowly lift one leg off the ground, keeping it straight and parallel to the floor. Rotate your leg outward, away from your body, while keeping your hips and upper body stable. Pause for a moment at the end of the rotation, then slowly return your leg to the starting position. Repeat the rotation with the other leg. Continue alternating legs for the desired number of repetitions.', 'Túmbate boca abajo sobre el balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti. Coloca las manos en el suelo frente a ti para mayor apoyo. Activa los glúteos y el abdomen para estabilizar el cuerpo. Levanta lentamente una pierna del suelo, manteniéndola recta y paralela al piso. Gira la pierna hacia afuera, alejándola del cuerpo, mientras mantienes las caderas y la parte superior del cuerpo estables. Haz una pausa al final de la rotación, luego regresa lentamente la pierna a la posición inicial. Repite la rotación con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","core"]'::jsonb, 'glutes', 'images/1416-M72BExt.jpg', 'videos/1416-M72BExt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1417', 'exercise ball one legged diagonal kick hamstring curl', 'upper legs', 'upper legs', 'stability ball', 'Start by lying on your back with your legs extended and your heels resting on top of the stability ball. Place your arms by your sides for stability. Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels. Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed. Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings. Slowly return your right leg to the starting position, maintaining control and stability. Repeat the movement with your left leg, alternating sides for the desired number of repetitions.', 'Comienza acostado sobre la espalda con las piernas extendidas y los talones apoyados sobre el balón de estabilidad. Coloca los brazos a los lados del cuerpo para mantener el equilibrio. Activa los glúteos y el abdomen para levantar las caderas del suelo, formando una línea recta desde los hombros hasta los talones. Dobla la rodilla derecha y llévala hacia el pecho, manteniendo la pierna izquierda extendida y el pie en flexión. Lleva la pierna derecha en diagonal a través del cuerpo, extendiéndola por completo y activando los isquiotibiales. Regresa lentamente la pierna derecha a la posición inicial, manteniendo el control y el equilibrio. Repite el movimiento con la pierna izquierda, alternando los lados durante el número de repeticiones deseado.', 'hamstrings', '["hamstrings","calves"]'::jsonb, 'glutes', 'images/1417-GOJKFfO.jpg', 'videos/1417-GOJKFfO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1296', 'exercise ball pike push up', 'chest', 'chest', 'stability ball', 'Start in a push-up position with your hands on the floor and your shins resting on the stability ball. Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands. Keep your legs straight and your body in a pike position, forming an inverted V shape. Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands. Push through your hands and extend your arms to return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión de brazos con las manos en el suelo y las espinillas apoyadas sobre el balón de estabilidad. Activa el core y levanta las caderas hacia el techo, haciendo rodar el balón hacia las manos. Mantén las piernas rectas y el cuerpo en posición de pica, formando una V invertida. Dobla los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo la cabeza alineada con las manos. Empuja con las manos y extiende los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps","core"]'::jsonb, 'pectorals', 'images/1296-sVvXT5J.jpg', 'videos/1296-sVvXT5J.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1343', 'exercise ball prone leg raise', 'back', 'back', 'stability ball', 'Lie face down on a mat with your legs extended and your toes resting on top of the stability ball. Place your hands on the ground, shoulder-width apart, and engage your core muscles. Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo sobre una esterilla con las piernas extendidas y los dedos de los pies apoyados sobre el balón de estabilidad. Coloca las manos en el suelo, separadas a la altura de los hombros, y activa el abdomen. Manteniendo las piernas rectas, levántalas lentamente del suelo, usando la zona lumbar y los glúteos para elevarlas tan alto como sea posible. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'abdominals', '["abdominals","glutes"]'::jsonb, 'spine', 'images/1343-lCKm4Rs.jpg', 'videos/1343-lCKm4Rs.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1560', 'exercise ball seated hamstring stretch', 'upper legs', 'upper legs', 'stability ball', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you. Place your hands on your hips for support. Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted. Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds. Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up. Repeat for the desired number of repetitions.', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Haz rodar el balón lentamente hacia adelante, caminando con los pies hacia afuera hasta que la parte superior de la espalda quede apoyada sobre el balón y las piernas queden extendidas rectas frente a ti. Coloca las manos en las caderas para mayor apoyo. Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, manteniendo la espalda recta y el pecho elevado. Detente cuando sientas un estiramiento en los isquiotibiales y mantén la posición durante 20-30 segundos. Regresa lentamente a la posición inicial empujando con los talones y usando los isquiotibiales para volver a subir. Repite el número de repeticiones deseado.', 'glutes', '["glutes","lower back"]'::jsonb, 'hamstrings', 'images/1560-yRYyfdA.jpg', 'videos/1560-yRYyfdA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1745', 'exercise ball seated triceps stretch', 'upper arms', 'upper arms', 'stability ball', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a dumbbell in one hand and extend your arm straight up above your head. Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear. Hold the stretch for a few seconds, then return to the starting position. Repeat with the other arm.', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sostén una mancuerna con una mano y extiende el brazo recto por encima de la cabeza. Dobla el codo y baja la mancuerna detrás de la cabeza, manteniendo el brazo cerca de la oreja. Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial. Repite con el otro brazo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1745-7ePTw4B.jpg', 'videos/1745-7ePTw4B.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1746', 'exercise ball supine triceps extension', 'upper arms', 'upper arms', 'dumbbell', 'Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a dumbbell with both hands and extend your arms straight up towards the ceiling. Slowly lower the dumbbell behind your head, keeping your elbows close to your ears. Pause for a moment, then raise the dumbbell back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia el techo. Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas. Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1746-Gm2Uv1z.jpg', 'videos/1746-Gm2Uv1z.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1747', 'ez bar french press on exercise ball', 'upper arms', 'upper arms', 'ez barbell', 'Sit on an exercise ball and hold an EZ barbell with an overhand grip. Extend your arms straight up, keeping your elbows close to your head. Slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de ejercicio y sostén una barra EZ con agarre prono. Extiende los brazos rectos hacia arriba, manteniendo los codos cerca de la cabeza. Baja lentamente la barra detrás de la cabeza doblando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1747-CFN9P8G.jpg', 'videos/1747-CFN9P8G.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3010', 'ez bar lying bent arms pullover', 'back', 'back', 'ez barbell', 'Lie flat on a bench with your head at one end and your feet on the floor. Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart. Extend your arms straight above your chest, keeping a slight bend in your elbows. Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows. Pause for a moment, then return the barbell to the starting position by reversing the arc motion. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sostén la barra EZ con agarre prono (palmas hacia afuera) y las manos separadas a la altura de los hombros. Extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos. Baja la barra describiendo un arco detrás de la cabeza, manteniendo la ligera flexión en los codos. Haz una pausa breve, luego regresa la barra a la posición inicial invirtiendo el movimiento del arco. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'lats', 'images/3010-nDK1HJ0.jpg', 'videos/3010-nDK1HJ0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1748', 'ez bar lying close grip triceps extension behind head', 'upper arms', 'upper arms', 'ez barbell', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench. Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest. Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sostén la barra EZ con agarre cerrado, palmas hacia arriba, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1748-6CKUx7o.jpg', 'videos/1748-6CKUx7o.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1344', 'ez bar reverse grip bent over row', 'back', 'back', 'ez barbell', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor. Pull the ez barbell towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the ez barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo. Tira de la barra EZ hacia la parte baja del pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte superior, luego baja lentamente la barra EZ a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1344-G8dXpNG.jpg', 'videos/1344-G8dXpNG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1682', 'ez bar seated close grip concentration curl', 'upper arms', 'upper arms', 'ez barbell', 'Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip. Rest your elbow on the inside of your thigh, just above the knee. Curl the barbell up towards your shoulder while keeping your upper arm stationary. Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados en el suelo y sostén una barra EZ con agarre supino. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Sube la barra curvando el brazo hacia el hombro mientras mantienes el brazo superior inmóvil. Contrae los bíceps en la parte superior del movimiento, luego baja lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1682-Dsfz0Id.jpg', 'videos/1682-Dsfz0Id.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1749', 'ez bar standing french press', 'upper arms', 'upper arms', 'ez barbell', 'Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip. Raise the barbell above your head, fully extending your arms. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1749-1cTf2Ux.jpg', 'videos/1749-1cTf2Ux.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0445', 'ez barbell anti gravity press', 'shoulders', 'shoulders', 'ez barbell', 'Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip. Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward. Press the barbell overhead, extending your arms fully. Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra EZ con agarre prono. Eleva la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y las palmas hacia adelante. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/0445-fprd84i.jpg', 'videos/0445-fprd84i.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1627', 'ez barbell close grip preacher curl', 'upper arms', 'upper arms', 'ez barbell', 'Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip. Rest your triceps on the pad and fully extend your arms, keeping your back straight. Slowly curl the barbell towards your shoulders, contracting your biceps. Pause for a moment at the top, squeezing your biceps. Lower the barbell back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Siéntate en un banco scott y coloca los brazos superiores sobre la almohadilla, sujetando la barra EZ con agarre supino. Apoya los tríceps sobre la almohadilla y extiende los brazos por completo, manteniendo la espalda recta. Sube lentamente la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte alta, apretando los bíceps. Baja la barra a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1627-hacCyUv.jpg', 'videos/1627-hacCyUv.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0446', 'ez barbell close-grip curl', 'upper arms', 'upper arms', 'ez barbell', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Curl the barbell up towards your shoulders, contracting your biceps. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Sube la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0446-V4ryaZa.jpg', 'videos/0446-V4ryaZa.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0447', 'ez barbell curl', 'upper arms', 'upper arms', 'ez barbell', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Exhale as you curl the barbell up towards your shoulders, contracting your biceps. Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Exhala mientras subes la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0447-6TG6x2w.jpg', 'videos/0447-6TG6x2w.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0448', 'ez barbell decline close grip face press', 'upper arms', 'upper arms', 'ez barbell', 'Lie on a decline bench with your head lower than your feet. Grasp the ez barbell with a close grip, palms facing each other. Extend your arms straight up above your chest, keeping your elbows close to your body. Lower the barbell towards your forehead by bending your elbows. Pause for a moment, then press the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con la cabeza más baja que los pies. Sujeta la barra EZ con agarre cerrado, palmas una frente a la otra. Extiende los brazos rectos por encima del pecho, manteniendo los codos cerca del cuerpo. Baja la barra hacia la frente doblando los codos. Haz una pausa breve, luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0448-DgZQ11d.jpg', 'videos/0448-DgZQ11d.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2186', 'ez barbell decline triceps extension', 'upper arms', 'upper arms', 'ez barbell', 'Lie on a decline bench with your head lower than your feet and your feet secured. Hold the ez barbell with an overhand grip, hands shoulder-width apart. Extend your arms fully, keeping your elbows close to your head. Lower the barbell slowly towards your forehead, bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco declinado con la cabeza más baja que los pies y los pies asegurados. Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros. Extiende completamente los brazos, manteniendo los codos cerca de la cabeza. Baja la barra lentamente hacia la frente, doblando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/2186-CQHoDm0.jpg', 'videos/2186-CQHoDm0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0449', 'ez barbell incline triceps extension', 'upper arms', 'upper arms', 'ez barbell', 'Set up an incline bench at a 45-degree angle. Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip. Extend your arms fully overhead, keeping your elbows close to your head. Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y sostén la barra EZ con agarre prono. Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza. Baja la barra detrás de la cabeza doblando los codos, manteniendo los brazos superiores inmóviles. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0449-KyLtiLT.jpg', 'videos/0449-KyLtiLT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0450', 'ez barbell jm bench press', 'upper arms', 'upper arms', 'ez barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart. Lower the barbell to your chest, keeping your elbows tucked in close to your body. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra EZ con agarre prono, ligeramente más ancho que la altura de los hombros. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0450-hnOYgH3.jpg', 'videos/0450-hnOYgH3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0451', 'ez barbell reverse grip curl', 'upper arms', 'upper arms', 'ez barbell', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip. Keep your elbows close to your torso and your upper arms stationary throughout the exercise. Curl the barbell upwards by contracting your biceps, while exhaling. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Slowly begin to bring the barbell back to the starting position as you inhale. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino. Mantén los codos cerca del torso y los brazos superiores inmóviles durante todo el ejercicio. Sube la barra contrayendo los bíceps, mientras exhalas. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Comienza a regresar la barra lentamente a la posición inicial mientras inhalas. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0451-Y5X65IB.jpg', 'videos/0451-Y5X65IB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0452', 'ez barbell reverse grip preacher curl', 'upper arms', 'upper arms', 'ez barbell', 'Sit on a preacher bench with your chest against the pad and your feet flat on the floor. Grasp the ez barbell with an underhand grip, hands shoulder-width apart. Rest your upper arms on the pad, allowing your forearms to hang down. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco scott con el pecho apoyado en la almohadilla y los pies planos sobre el suelo. Sujeta la barra EZ con agarre supino, manos separadas a la altura de los hombros. Apoya los brazos superiores en la almohadilla, dejando que los antebrazos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0452-vBNyir7.jpg', 'videos/0452-vBNyir7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1458', 'ez barbell seated curls', 'upper arms', 'upper arms', 'ez barbell', 'Sit on a bench with your feet flat on the ground and your back straight. Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart. Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you. Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the ez barbell back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Apoya los brazos superiores en los muslos, dejando que la barra EZ cuelgue frente a ti. Manteniendo los brazos superiores inmóviles, exhala y sube la barra EZ hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra EZ a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1458-jtFKbt5.jpg', 'videos/1458-jtFKbt5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0453', 'ez barbell seated triceps extension', 'upper arms', 'upper arms', 'ez barbell', 'Sit on a bench with your back straight and feet flat on the ground. Hold the ez barbell with an overhand grip, hands shoulder-width apart. Raise the barbell overhead, fully extending your arms. Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows. Pause for a moment, then raise the barbell back to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores inmóviles, baja la barra detrás de la cabeza doblando los codos. Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0453-iaapw0g.jpg', 'videos/0453-iaapw0g.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0454', 'ez barbell spider curl', 'upper arms', 'upper arms', 'ez barbell', 'Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up. Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0454-Ye5Qxb0.jpg', 'videos/0454-Ye5Qxb0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1628', 'ez barbell spider curl', 'upper arms', 'upper arms', 'ez barbell', 'Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up. Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down. Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1628-2kattbR.jpg', 'videos/1628-2kattbR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2404', 'ez-bar biceps curl (with arm blaster)', 'upper arms', 'upper arms', 'ez barbell', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up. Place your upper arms against the arm blaster, keeping them stationary throughout the exercise. Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the barbell back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba. Coloca los brazos superiores contra el soporte de aislamiento de brazos, manteniéndolos inmóviles durante todo el ejercicio. Manteniendo los codos cerca del cuerpo, exhala y sube la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2404-tJ5nYqo.jpg', 'videos/2404-tJ5nYqo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2432', 'ez-bar close-grip bench press', 'upper arms', 'upper arms', 'ez barbell', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench. Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward. Lift the barbell off the rack and hold it directly above your chest with your arms fully extended. Slowly lower the barbell towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra EZ con agarre cerrado, manos separadas a la altura de los hombros, palmas hacia adelante. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/2432-da4cXST.jpg', 'videos/2432-da4cXST.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2741', 'ez-barbell standing wide grip biceps curl', 'upper arms', 'upper arms', 'ez barbell', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart. Keep your elbows close to your torso and your upper arms stationary throughout the movement. Curl the barbell up towards your shoulders by contracting your biceps. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos más separadas que la altura de los hombros. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Sube la barra hacia los hombros contrayendo los bíceps. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/2741-OVTZ65k.jpg', 'videos/2741-OVTZ65k.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2133', 'farmers walk', 'upper legs', 'upper legs', 'dumbbell', 'Stand up straight with a dumbbell in each hand, palms facing your sides. Keep your back straight and your shoulders back. Take small, controlled steps forward, maintaining an upright posture. Continue walking for the desired distance or time. To finish, stop walking and carefully lower the dumbbells to your sides.', 'Ponte de pie con una mancuerna en cada mano, palmas hacia los costados. Mantén la espalda recta y los hombros hacia atrás. Da pasos pequeños y controlados hacia adelante, manteniendo una postura erguida. Continúa caminando durante la distancia o el tiempo deseado. Para terminar, deja de caminar y baja con cuidado las mancuernas a los costados.', 'calves', '["calves","forearms","core"]'::jsonb, 'quads', 'images/2133-qPEzJjA.jpg', 'videos/2133-qPEzJjA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0455', 'finger curls', 'lower arms', 'lower arms', 'barbell', 'Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up. Rest your forearms on your thighs, allowing your wrists to hang off the edge. Slowly curl your fingers towards your palms, squeezing the barbell tightly. Hold the contraction for a moment, then slowly release your fingers back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Curva lentamente los dedos hacia las palmas, apretando la barra con fuerza. Mantén la contracción por un momento, luego suelta lentamente los dedos hasta la posición inicial. Repite el número de repeticiones deseado.', 'wrist flexors', '["wrist flexors","grip muscles"]'::jsonb, 'forearms', 'images/0455-awG04cF.jpg', 'videos/0455-awG04cF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3303', 'flag', 'waist', 'waist', 'body weight', 'Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended. Engage your core and lift your legs off the ground, keeping them straight. Using your core and upper body strength, raise your legs until they are parallel to the ground. Hold this position for as long as you can, maintaining a straight body line. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza sujetando un poste vertical con ambas manos, palmas una frente a la otra, y los brazos completamente extendidos. Activa el core y levanta las piernas del suelo, manteniéndolas rectas. Usando la fuerza del core y de la parte superior del cuerpo, levanta las piernas hasta que queden paralelas al suelo. Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques","shoulders"]'::jsonb, 'abs', 'images/3303-pQ0Mx1Z.jpg', 'videos/3303-pQ0Mx1Z.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0456', 'flexion leg sit up (bent knee)', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest. Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Al mismo tiempo, levanta las piernas del suelo, doblando las rodillas y llevándolas hacia el pecho. Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0456-AR0ig3o.jpg', 'videos/0456-AR0ig3o.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0457', 'flexion leg sit up (straight arm)', 'waist', 'waist', 'body weight', 'Lie flat on your back with your legs extended and arms straight above your head. Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest. Reach your hands towards your toes as you lift your upper body and legs. Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba con las piernas extendidas y los brazos rectos por encima de la cabeza. Activando el abdomen, levanta la parte superior del cuerpo del suelo mientras al mismo tiempo levantas las piernas hacia el pecho. Extiende las manos hacia los dedos de los pies mientras levantas la parte superior del cuerpo y las piernas. Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","quadriceps"]'::jsonb, 'abs', 'images/0457-KZn52RC.jpg', 'videos/0457-KZn52RC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0458', 'floor fly (with barbell)', 'chest', 'chest', 'barbell', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground. Hold a barbell with an overhand grip, arms extended straight up over your chest. Slowly lower the barbell out to the sides, keeping a slight bend in your elbows. Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest. Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sostén una barra con agarre prono, brazos extendidos rectos por encima del pecho. Baja lentamente la barra hacia los lados, manteniendo una ligera flexión en los codos. Baja la barra hasta que los brazos queden paralelos al suelo, sintiendo un estiramiento en el pecho. Haz una pausa breve, luego contrae los músculos del pecho para llevar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/0458-neonEDL.jpg', 'videos/0458-neonEDL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0459', 'flutter kicks', 'upper legs', 'upper legs', 'body weight', 'Lie flat on your back with your legs extended and your hands by your sides. Engage your core and lift your legs off the ground about 6 inches. Keeping your legs straight, alternate lifting one leg slightly higher than the other. Continue this fluttering motion for the desired number of repetitions.', 'Túmbate boca arriba con las piernas extendidas y las manos a los costados. Activa el core y levanta las piernas del suelo unos 15 centímetros. Manteniendo las piernas rectas, alterna levantando una pierna ligeramente más alto que la otra. Continúa este movimiento de aleteo durante el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower abs"]'::jsonb, 'glutes', 'images/0459-UVo2Qs2.jpg', 'videos/0459-UVo2Qs2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1472', 'forward jump', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Swing your arms back for momentum. Jump forward explosively, extending your hips, knees, and ankles. Land softly on the balls of your feet and immediately go into the next jump. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Balancea los brazos hacia atrás para generar impulso. Salta hacia adelante de forma explosiva, extendiendo las caderas, las rodillas y los tobillos. Aterriza suavemente sobre la punta de los pies y pasa de inmediato al siguiente salto. Repite el número de repeticiones deseado.', 'calves', '["calves","hamstrings","glutes"]'::jsonb, 'quads', 'images/1472-uZKq7lo.jpg', 'videos/1472-uZKq7lo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3470', 'forward lunge (male)', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet hip-width apart and hands on your hips. Take a big step forward with your right foot, lowering your body into a lunge position. Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle. Push off with your right foot and return to the starting position. Repeat with your left leg, alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas. Da un paso grande hacia adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Dobla la rodilla derecha hasta unos 90 grados, manteniendo la rodilla alineada con el tobillo. Empuja con el pie derecho y vuelve a la posición inicial. Repite con la pierna izquierda, alternando los lados durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3470-kMzUs9Y.jpg', 'videos/3470-kMzUs9Y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3194', 'frankenstein squat', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms. Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra frente al cuerpo con los brazos rectos. Manteniendo la espalda recta, baja el cuerpo flexionando las rodillas y las caderas, como si fueras a sentarte en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3194-bdWcbaU.jpg', 'videos/3194-bdWcbaU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2429', 'frog crunch', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/2429-FFRP97T.jpg', 'videos/2429-FFRP97T.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3301', 'frog planche', 'waist', 'waist', 'body weight', 'Start in a push-up position with your hands shoulder-width apart and your feet together. Bend your elbows and lower your body towards the ground, keeping your back straight. As you lower your body, lift your feet off the ground and bring your knees towards your chest. Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los pies juntos. Dobla los codos y baja el cuerpo hacia el suelo, manteniendo la espalda recta. Mientras bajas el cuerpo, levanta los pies del suelo y lleva las rodillas hacia el pecho. Mantén esta posición durante unos segundos, luego extiende las piernas de nuevo y empújate hacia arriba a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest","triceps"]'::jsonb, 'abs', 'images/3301-rQhGcin.jpg', 'videos/3301-rQhGcin.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3296', 'front lever', 'waist', 'waist', 'body weight', 'Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart. Engage your core and pull your shoulder blades down and back. Bend your knees and tuck them towards your chest. Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground. Hold this position for as long as you can, aiming for a full front lever position. To release, slowly lower your legs back down and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza colgado de una barra de dominadas con agarre prono, manos separadas a la altura de los hombros. Activa el core y lleva los omóplatos hacia abajo y atrás. Flexiona las rodillas y llévalas hacia el pecho. Al mismo tiempo, levanta las piernas y extiéndelas rectas frente a ti, manteniendo el cuerpo paralelo al suelo. Mantén esta posición todo el tiempo que puedas, intentando lograr una posición completa de palanca frontal. Para soltar, baja lentamente las piernas y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'lats', '["lats","shoulders","forearms"]'::jsonb, 'abs', 'images/3296-PkCN2lv.jpg', 'videos/3296-PkCN2lv.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3295', 'front lever reps', 'back', 'back', 'body weight', 'Hang from a pull-up bar with an overhand grip, palms facing away from you. Engage your core and pull your shoulder blades down and back. Keeping your body straight, lift your legs up until they are parallel to the ground. Hold this position for as long as you can, aiming for 10-20 seconds. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con agarre prono, palmas hacia afuera. Activa el core y lleva los omóplatos hacia abajo y atrás. Manteniendo el cuerpo recto, levanta las piernas hasta que queden paralelas al suelo. Mantén esta posición todo el tiempo que puedas, intentando llegar a 10-20 segundos. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'core', '["core","shoulders"]'::jsonb, 'upper back', 'images/3295-hbY9wqG.jpg', 'videos/3295-hbY9wqG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0464', 'front plank with twist', 'waist', 'waist', 'body weight', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe. Engage your core and glutes to maintain a stable position. Rotate your torso to the right, lifting your right arm and extending it towards the ceiling. Keep your hips and legs stable as you twist. Hold for a moment, then return to the starting position. Repeat the twist on the left side. Continue alternating sides for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies. Activa el core y los glúteos para mantener una posición estable. Gira el torso hacia la derecha, levantando el brazo derecho y extendiéndolo hacia el techo. Mantén las caderas y las piernas estables mientras giras. Mantén la posición por un momento, luego regresa a la posición inicial. Repite el giro hacia el lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","shoulders"]'::jsonb, 'abs', 'images/0464-CosupLu.jpg', 'videos/0464-CosupLu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3315', 'full maltese', 'waist', 'waist', 'body weight', 'Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides. Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground. Engage your core and hold this position for a few seconds. Return to the starting position by pushing through your feet and standing back up. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos rectos hacia los lados. Inclínate lentamente hacia adelante, manteniendo los brazos rectos, hasta que la parte superior del cuerpo quede paralela al suelo. Activa el core y mantén esta posición durante unos segundos. Regresa a la posición inicial empujando con los pies y volviendo a ponerte de pie. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest"]'::jsonb, 'abs', 'images/3315-YRaCa5Y.jpg', 'videos/3315-YRaCa5Y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3299', 'full planche', 'waist', 'waist', 'body weight', 'Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward. Engage your core and slowly shift your weight forward, lifting your feet off the ground. Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands. Hold this position for as long as you can, maintaining a straight body line. Slowly lower your feet back to the ground and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los dedos apuntando hacia adelante. Activa el core y desplaza lentamente el peso hacia adelante, levantando los pies del suelo. Continúa desplazando el peso hacia adelante hasta que el cuerpo quede paralelo al suelo, equilibrándote sobre las manos. Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta. Baja lentamente los pies de nuevo al suelo y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest","triceps"]'::jsonb, 'abs', 'images/3299-YZ4961r.jpg', 'videos/3299-YZ4961r.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3327', 'full planche push-up', 'chest', 'chest', 'body weight', 'Start in a push-up position with your hands placed slightly wider than shoulder-width apart. Engage your core and lower your body down towards the ground, keeping your elbows close to your sides. As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands. Continue to lower your body until your chest is just above the ground. Push through your hands and extend your arms to lift your body back up to the starting position. Maintain a straight line from your head to your heels throughout the movement. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Mientras te bajas, inclina el cuerpo hacia adelante y levanta los pies del suelo, equilibrándote sobre las manos. Continúa bajando el cuerpo hasta que el pecho quede justo por encima del suelo. Empuja con las manos y extiende los brazos para volver a subir el cuerpo a la posición inicial. Mantén una línea recta desde la cabeza hasta los talones durante todo el movimiento. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps","core"]'::jsonb, 'pectorals', 'images/3327-gw9PqGk.jpg', 'videos/3327-gw9PqGk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0466', 'gironda sternum chin', 'back', 'back', 'body weight', 'Stand facing a high bar with your feet shoulder-width apart. Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum. Pause for a moment at the top, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una barra alta con los pies separados a la altura de los hombros. Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los dorsales y los bíceps para llevar el pecho hacia la barra, guiando con el esternón. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/0466-IL0JUxR.jpg', 'videos/0466-IL0JUxR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3561', 'glute bridge march', 'upper legs', 'upper legs', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders. While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest. Lower your foot back to the ground and repeat the movement with the other leg. Continue alternating legs in a marching motion while maintaining the bridge position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros. Manteniendo las caderas elevadas, levanta un pie del suelo y lleva la rodilla hacia el pecho. Baja el pie de nuevo al suelo y repite el movimiento con la otra pierna. Continúa alternando las piernas con un movimiento de marcha mientras mantienes la posición de puente. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/3561-GibBPPg.jpg', 'videos/3561-GibBPPg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3523', 'glute bridge two legs on bench (male)', 'upper legs', 'upper legs', 'body weight', 'Sit on the edge of a bench with your back against it and your feet flat on the ground. Place your hands on the bench beside your hips for support. Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco con la espalda apoyada en él y los pies planos sobre el suelo. Coloca las manos en el banco junto a las caderas para mayor apoyo. Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","core"]'::jsonb, 'glutes', 'images/3523-aWedzZX.jpg', 'videos/3523-aWedzZX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3193', 'glute-ham raise', 'upper legs', 'upper legs', 'body weight', 'Adjust the glute-ham raise machine to fit your body. Position yourself face down on the machine with your ankles secured. Place your hands on your chest or cross them over your chest. Engage your hamstrings and glutes to lift your upper body up towards the ceiling. Continue lifting until your body is in a straight line from your head to your heels. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de extensión de glúteos e isquiotibiales para que se adapte a tu cuerpo. Colócate boca abajo en la máquina con los tobillos asegurados. Coloca las manos sobre el pecho o crúzalas sobre el pecho. Activa los isquiotibiales y los glúteos para levantar la parte superior del cuerpo hacia el techo. Continúa levantando hasta que el cuerpo forme una línea recta desde la cabeza hasta los talones. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","lower back"]'::jsonb, 'hamstrings', 'images/3193-Vvwjz6N.jpg', 'videos/3193-Vvwjz6N.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0467', 'gorilla chin', 'waist', 'waist', 'body weight', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your palms facing away from you. Engage your core and pull your body up towards the bar, bringing your chin above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra de dominadas con agarre prono, ligeramente más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y las palmas hacia afuera. Activa el core y tira del cuerpo hacia la barra, llevando la barbilla por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms","biceps"]'::jsonb, 'abs', 'images/0467-bmwlYvD.jpg', 'videos/0467-bmwlYvD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0469', 'groin crunch', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your legs off the ground, bringing your knees towards your chest. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","inner thighs"]'::jsonb, 'abs', 'images/0469-mWppALS.jpg', 'videos/0469-mWppALS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1383', 'hack calf raise', 'lower legs', 'lower legs', 'sled machine', 'Adjust the sled machine to a comfortable weight. Stand on the sled machine with your toes on the platform and your heels hanging off. Hold onto the handles for stability. Raise your heels as high as possible by pushing through the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de trineo a un peso adecuado. Ponte de pie sobre la máquina de trineo con la punta de los pies en la plataforma y los talones colgando. Sujétate de las asas para mantener el equilibrio. Levanta los talones lo más alto posible empujando con la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1383-2ORFMoR.jpg', 'videos/1383-2ORFMoR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1384', 'hack one leg calf raise', 'lower legs', 'lower legs', 'sled machine', 'Adjust the sled machine to an appropriate weight. Stand on the sled machine with one foot, keeping the other foot off the ground. Hold onto the handles for stability. Raise your heel as high as possible, lifting your body up on the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions. Switch legs and repeat the exercise.', 'Ajusta la máquina de trineo a un peso adecuado. Ponte de pie sobre la máquina de trineo con un pie, manteniendo el otro pie levantado del suelo. Sujétate de las asas para mantener el equilibrio. Levanta el talón lo más alto posible, elevando el cuerpo sobre la punta del pie. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de pierna y repite el ejercicio.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1384-AxFoqAD.jpg', 'videos/1384-AxFoqAD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3221', 'half knee bends (male)', 'cardio', 'cardio', 'body weight', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body down as if you were sitting back into a chair. Keep your chest up and your weight in your heels. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Dobla las rodillas y baja el cuerpo como si te fueras a sentar en una silla. Mantén el pecho elevado y el peso en los talones. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","glutes"]'::jsonb, 'cardiovascular system', 'images/3221-ia6kIIl.jpg', 'videos/3221-ia6kIIl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3202', 'half sit-up (male)', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/3202-iQ241UP.jpg', 'videos/3202-iQ241UP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1511', 'hamstring stretch', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Step forward with your right foot and shift your weight onto your right leg. Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands. Hold the stretch for 20-30 seconds, then return to the starting position. Repeat on the other side.', 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho y traslada el peso hacia la pierna derecha. Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas, alcanzando el pie derecho con ambas manos. Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial. Repite del otro lado.', 'glutes', '["glutes"]'::jsonb, 'hamstrings', 'images/1511-99rWm7w.jpg', 'videos/1511-99rWm7w.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2139', 'hands bike', 'chest', 'chest', 'upper body ergometer', 'Adjust the seat height and handlebar position to a comfortable level. Sit on the ergometer with your back straight and feet on the pedals. Grasp the handles with your hands and position your arms at a 90-degree angle. Start pedaling with your hands, pushing and pulling the handles in a controlled motion. Continue pedaling for the desired duration or number of repetitions.', 'Ajusta la altura del asiento y la posición del manillar a un nivel cómodo. Siéntate en el ergómetro con la espalda recta y los pies sobre los pedales. Sujeta las asas con las manos y coloca los brazos en un ángulo de 90 grados. Comienza a pedalear con las manos, empujando y tirando de las asas con un movimiento controlado. Continúa pedaleando durante el tiempo o el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/2139-pAIWRGu.jpg', 'videos/2139-pAIWRGu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3218', 'hands clasped circular toe touch (male)', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and your hands clasped together in front of your chest. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower your hands towards your toes in a circular motion, reaching as far as you can without straining. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las manos entrelazadas frente al pecho. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja las manos hacia los dedos de los pies con un movimiento circular, llegando tan lejos como puedas sin forzar. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","calves"]'::jsonb, 'glutes', 'images/3218-B5xca8s.jpg', 'videos/3218-B5xca8s.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3215', 'hands reversed clasped circular toe touch (male)', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and your arms extended to the sides. Bend forward at the waist, keeping your back straight and your knees slightly bent. Reach down with your hands and clasp them together behind your legs. Slowly raise your hands up and over your head in a circular motion, keeping your legs straight. Continue the circular motion until your hands touch your toes. Reverse the motion and bring your hands back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende las manos hacia abajo y entrelázalas detrás de las piernas. Sube lentamente las manos en un movimiento circular por encima de la cabeza, manteniendo las piernas rectas. Continúa el movimiento circular hasta que las manos toquen los dedos de los pies. Invierte el movimiento y regresa las manos a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","calves"]'::jsonb, 'glutes', 'images/3215-yq3GAJX.jpg', 'videos/3215-yq3GAJX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3302', 'handstand', 'upper arms', 'upper arms', 'body weight', 'Find an open space with enough room to perform a handstand. Place your hands on the ground shoulder-width apart, fingers pointing forward. Kick your legs up towards the wall, using your core and shoulders to maintain balance. Once in a handstand position, engage your triceps to support your body weight. Hold the handstand for as long as you can maintain balance. To come down, slowly lower your legs back to the ground. Repeat for the desired number of repetitions.', 'Busca un espacio abierto con suficiente espacio para hacer un pino. Coloca las manos en el suelo separadas a la altura de los hombros, con los dedos apuntando hacia adelante. Lanza las piernas hacia la pared, usando el core y los hombros para mantener el equilibrio. Una vez en posición de pino, activa los tríceps para sostener el peso corporal. Mantén el pino el mayor tiempo posible mientras conserves el equilibrio. Para bajar, lleva lentamente las piernas de vuelta al suelo. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","core"]'::jsonb, 'triceps', 'images/3302-XooAdhl.jpg', 'videos/3302-XooAdhl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0471', 'handstand push-up', 'upper arms', 'upper arms', 'body weight', 'Find a wall and face away from it, standing a few feet away. Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position. Bend your elbows and lower your head towards the ground, keeping your body in a straight line. Push through your hands and extend your arms to return to the starting position. Repeat for the desired number of repetitions.', 'Busca una pared y colócate de espaldas a ella, de pie a unos pasos de distancia. Coloca las manos en el suelo separadas a la altura de los hombros y lanza los pies hacia la pared, llegando a una posición de pino. Dobla los codos y baja la cabeza hacia el suelo, manteniendo el cuerpo en línea recta. Empuja con las manos y extiende los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest","core"]'::jsonb, 'triceps', 'images/0471-rQxwMxO.jpg', 'videos/0471-rQxwMxO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1764', 'hanging leg hip raise', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas flexionando las caderas y las rodillas hasta que los muslos queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/1764-VEcJRo2.jpg', 'videos/1764-VEcJRo2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0472', 'hanging leg raise', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or as high as you can comfortably go. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0472-I3tsCnC.jpg', 'videos/0472-I3tsCnC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1761', 'hanging oblique knee raise', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat on the other side, twisting your torso in the opposite direction. Continue alternating sides for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las rodillas hacia el pecho, girando el torso hacia un lado mientras lo haces. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite hacia el otro lado, girando el torso en la dirección opuesta. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/1761-BaE7O6U.jpg', 'videos/1761-BaE7O6U.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0473', 'hanging pike', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up towards the bar, keeping them straight. Continue lifting until your body forms a ''V'' shape, with your legs parallel to the ground. Hold the position for a moment, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas hacia la barra, manteniéndolas rectas. Continúa levantando hasta que el cuerpo forme una ''V'', con las piernas paralelas al suelo. Mantén la posición por un momento, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","shoulders"]'::jsonb, 'abs', 'images/0473-nuBF9MO.jpg', 'videos/0473-nuBF9MO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0474', 'hanging straight leg hip raise', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up in front of you until they are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0474-pj0X0tF.jpg', 'videos/0474-pj0X0tF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0475', 'hanging straight leg raise', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or as high as you can comfortably go. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0475-4Ml7QFO.jpg', 'videos/0475-4Ml7QFO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0476', 'hanging straight twisting leg hip raise', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your legs straight. Engage your core and lift your legs up towards your chest, keeping them straight. Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side. Pause for a moment, then return to the starting position. Repeat the movement, but this time twist your hips to the opposite side. Continue alternating sides for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas rectas. Activa el core y levanta las piernas hacia el pecho, manteniéndolas rectas. Cuando las piernas queden paralelas al suelo, gira las caderas hacia un lado, llevando las piernas hacia ese lado. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento, pero esta vez gira las caderas hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/0476-Q6bvyen.jpg', 'videos/0476-Q6bvyen.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3636', 'high knee against wall', 'cardio', 'cardio', 'body weight', 'Stand facing a wall with your feet hip-width apart. Place your hands on the wall for support. Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground. Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down. Continue alternating legs in a running motion, bringing your knees up as high as possible. Maintain a fast pace and keep your upper body stable throughout the exercise. Repeat for the desired duration or number of repetitions.', 'Ponte de pie frente a una pared con los pies separados a la altura de las caderas. Coloca las manos en la pared para mayor apoyo. Activa el core y levanta la rodilla derecha hacia el pecho, mientras mantienes el pie izquierdo en el suelo. Cambia rápidamente de pierna, llevando la rodilla izquierda hacia el pecho y bajando el pie derecho de nuevo. Continúa alternando las piernas con un movimiento de carrera, llevando las rodillas lo más alto posible. Mantén un ritmo rápido y la parte superior del cuerpo estable durante todo el ejercicio. Repite durante la duración o el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","glutes","calves"]'::jsonb, 'cardiovascular system', 'images/3636-ealLwvX.jpg', 'videos/3636-ealLwvX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0484', 'hip raise (bent knee)', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands by your sides, palms facing down. Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados, con las palmas hacia abajo. Activa el core y los glúteos, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'abs', 'images/0484-196HJGw.jpg', 'videos/0484-196HJGw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1418', 'hug keens to chest', 'upper legs', 'upper legs', 'body weight', 'Start by standing with your feet shoulder-width apart. Bend your knees and lower your body down into a squat position. As you squat down, bring your knees up towards your chest and hug them with your arms. Hold this position for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Al ponerte en cuclillas, lleva las rodillas hacia el pecho y abrázalas con los brazos. Mantén esta posición por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/1418-znP9SIh.jpg', 'videos/1418-znP9SIh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3234', 'hyght dumbbell fly', 'chest', 'chest', 'dumbbell', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other. Extend your arms straight up over your chest, with a slight bend in your elbows. Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest. Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Manteniendo una ligera flexión en los codos, baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'pectorals', 'images/3234-P9ZRyLT.jpg', 'videos/3234-P9ZRyLT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0489', 'hyperextension', 'back', 'back', 'body weight', 'Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured. Cross your arms over your chest or place your hands behind your head. Lower your upper body towards the ground while keeping your back straight. Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs. Repeat for the desired number of repetitions.', 'Ajusta el banco de hiperextensiones para que la parte superior de los muslos quede apoyada en la almohadilla y los pies queden asegurados. Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza. Baja la parte superior del cuerpo hacia el suelo manteniendo la espalda recta. Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/0489-zhMwOwE.jpg', 'videos/0489-zhMwOwE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0488', 'hyperextension (on bench)', 'back', 'back', 'body weight', 'Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured. Cross your arms over your chest or place your hands behind your head. Slowly lower your upper body towards the ground while keeping your back straight. Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs. Repeat for the desired number of repetitions.', 'Ajusta el banco de hiperextensiones para que las caderas queden apoyadas cómodamente en la almohadilla y los pies queden asegurados. Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza. Baja lentamente la parte superior del cuerpo hacia el suelo manteniendo la espalda recta. Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/0488-zkgRrbK.jpg', 'videos/0488-zkgRrbK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3289', 'impossible dips', 'upper arms', 'upper arms', 'body weight', 'Position yourself between two parallel bars with your arms fully extended and your body suspended in the air. Bend your knees and cross your ankles. Lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire. Flexiona las rodillas y cruza los tobillos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/3289-05Cf2v8.jpg', 'videos/3289-05Cf2v8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1471', 'inchworm', 'waist', 'waist', 'body weight', 'Start in a standing position with your feet hip-width apart. Bend forward at the waist and place your hands on the ground in front of you. Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe. Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible. Once your hands reach your feet, stand back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de las caderas. Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti. Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies. Haz una pausa breve, luego camina con las manos de vuelta hacia los pies, manteniendo las piernas lo más rectas posible. Cuando las manos lleguen a los pies, ponte de pie de nuevo en la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","hamstrings"]'::jsonb, 'abs', 'images/1471-ZgsNQ6d.jpg', 'videos/1471-ZgsNQ6d.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3698', 'inchworm v. 2', 'waist', 'waist', 'body weight', 'Start in a standing position with your feet hip-width apart. Bend forward at the waist and place your hands on the ground in front of you. Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe. Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling. Continue walking your hands forward, repeating the movement for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de las caderas. Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti. Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies. Manteniendo las piernas rectas, camina con los pies hacia las manos, llevando las caderas hacia el techo. Continúa caminando con las manos hacia adelante, repitiendo el movimiento durante el número de repeticiones deseado.', 'shoulders', '["shoulders","hamstrings"]'::jsonb, 'abs', 'images/3698-TV87DNB.jpg', 'videos/3698-TV87DNB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0490', 'incline close-grip push-up', 'upper arms', 'upper arms', 'body weight', 'Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart. Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels. Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, con el cuerpo formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la superficie elevada doblando los codos, manteniéndolos cerca de los costados. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0490-1YB40kg.jpg', 'videos/0490-1YB40kg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0491', 'incline leg hip raise (leg straight)', 'waist', 'waist', 'body weight', 'Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you. Place your hands on the sides of the bench for support. Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco inclinado con la espalda apoyada plana en el banco y las piernas extendidas rectas frente a ti. Coloca las manos a los lados del banco para apoyarte. Activando el abdomen, levanta las piernas del banco, elevándolas tan alto como puedas mientras las mantienes rectas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0491-eVxAzgz.jpg', 'videos/0491-eVxAzgz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0492', 'incline push up depth jump', 'chest', 'chest', 'body weight', 'Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge. Step your feet back, keeping your body in a straight line from head to heels. Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned. Push through your palms to extend your arms and return to the starting position. Jump off the edge of the surface, landing softly with your knees slightly bent. Repeat the push-up and depth jump for the desired number of repetitions.', 'Busca una superficie elevada, como un banco o un escalón, y coloca las manos separadas a la altura de los hombros en el borde. Da un paso hacia atrás con los pies, manteniendo el cuerpo en línea recta desde la cabeza hasta los talones. Baja el pecho hacia el borde de la superficie, doblando los codos y manteniendo el cuerpo alineado. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Salta desde el borde de la superficie, aterrizando suavemente con las rodillas ligeramente flexionadas. Repite la flexión de brazos y el salto en profundidad durante el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0492-CB8WET1.jpg', 'videos/0492-CB8WET1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0493', 'incline push-up', 'chest', 'chest', 'body weight', 'Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels. Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la superficie elevada doblando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0493-B1EVP9F.jpg', 'videos/0493-B1EVP9F.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3785', 'incline push-up (on box)', 'chest', 'chest', 'body weight', 'Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels. Lower your chest towards the box by bending your elbows, keeping your body in a straight line. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Coloca las manos en el borde de una caja o una superficie elevada, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia la caja doblando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/3785-F7vjXqT.jpg', 'videos/3785-F7vjXqT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0494', 'incline reverse grip push-up', 'chest', 'chest', 'body weight', 'Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels. Lower your chest towards the bench by bending your elbows, keeping them close to your sides. Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Coloca las manos en el borde de un banco o una superficie elevada, ligeramente más separadas que la altura de los hombros. Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones. Baja el pecho hacia el banco doblando los codos, manteniéndolos cerca de los costados. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0494-XaaRnRn.jpg', 'videos/0494-XaaRnRn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3011', 'incline scapula push up', 'chest', 'chest', 'body weight', 'Set up an incline bench at a 45-degree angle. Place your hands on the bench slightly wider than shoulder-width apart. Position your feet on the ground, hip-width apart. Lower your chest towards the bench, keeping your elbows tucked in. As you lower, retract your shoulder blades, squeezing your scapulae together. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros. Coloca los pies en el suelo, separados a la altura de las caderas. Baja el pecho hacia el banco, manteniendo los codos pegados al cuerpo. Mientras bajas, retrae los omóplatos, apretándolos entre sí. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'serratus anterior', 'images/3011-GdMa1ET.jpg', 'videos/3011-GdMa1ET.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0495', 'incline twisting sit-up', 'waist', 'waist', 'body weight', 'Set up an incline bench at a 45-degree angle. Lie down on the bench with your feet secured under the foot pads. Place your hands behind your head or across your chest. Engage your abs and lift your upper body off the bench, curling forward. As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat the movement, this time twisting your torso to the other side. Continue alternating sides for the desired number of repetitions.', 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del banco, curvándote hacia adelante. Mientras te incorporas, gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el movimiento, esta vez girando el torso hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0495-9ZGZuOD.jpg', 'videos/0495-9ZGZuOD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1564', 'intermediate hip flexor and quad stretch', 'upper legs', 'upper legs', 'rope', 'Stand upright with your feet shoulder-width apart. Hold onto a stable object for support. Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand. Slowly pull your right foot towards your glutes, feeling a stretch in your right quad. Hold the stretch for 20-30 seconds. Release the stretch and repeat on the left side.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Sujétate de un objeto estable para mayor apoyo. Dobla la rodilla derecha y lleva el pie derecho hacia los glúteos, sujetando la cuerda con la mano derecha. Tira lentamente del pie derecho hacia los glúteos, sintiendo un estiramiento en el cuádriceps derecho. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite en el lado izquierdo.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'quads', 'images/1564-tFGKm99.jpg', 'videos/1564-tFGKm99.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0496', 'inverse leg curl (bench support)', 'upper legs', 'upper legs', 'body weight', 'Lie face down on a bench with your hips at the edge and your legs extended straight behind you. Hold onto the bench for support. Keeping your upper body still, bend your knees and curl your legs towards your glutes. Pause for a moment at the top, then slowly extend your legs back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en un banco con las caderas en el borde y las piernas extendidas rectas detrás de ti. Sujétate del banco para mayor apoyo. Manteniendo la parte superior del cuerpo quieta, dobla las rodillas y curva las piernas hacia los glúteos. Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","calves"]'::jsonb, 'hamstrings', 'images/0496-ms7tjSG.jpg', 'videos/0496-ms7tjSG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2400', 'inverse leg curl (on pull-up cable machine)', 'upper legs', 'upper legs', 'body weight', 'Adjust the cable machine so that the ankle straps are at the lowest setting. Lie face down on the bench with your legs extended and the ankle straps attached to your feet. Hold onto the handles of the bench for stability. Bend your knees and curl your legs towards your glutes, squeezing your hamstrings. Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de cable para que las correas de tobillo estén en el ajuste más bajo. Túmbate boca abajo en el banco con las piernas extendidas y las correas de tobillo sujetas a los pies. Sujétate de las agarraderas del banco para mantener la estabilidad. Dobla las rodillas y curva las piernas hacia los glúteos, contrayendo los isquiotibiales. Haz una pausa breve en la parte superior del movimiento, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","calves"]'::jsonb, 'hamstrings', 'images/2400-0rHfvy9.jpg', 'videos/2400-0rHfvy9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0499', 'inverted row', 'back', 'back', 'body weight', 'Set up a bar at waist height or use a suspension trainer. Stand facing the bar or suspension trainer, with your feet shoulder-width apart. Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart. Lean back, keeping your body straight and your heels on the ground. Pull your chest towards the bar or handles, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower yourself back to the starting position. Repeat for the desired number of repetitions.', 'Coloca una barra a la altura de la cintura o usa un entrenador de suspensión. Ponte de pie frente a la barra o al entrenador de suspensión, con los pies separados a la altura de los hombros. Agarra la barra o las asas con agarre prono, ligeramente más ancho que la altura de los hombros. Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo. Tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0499-bZGHsAZ.jpg', 'videos/0499-bZGHsAZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2300', 'inverted row bent knees', 'back', 'back', 'body weight', 'Set up a bar at waist height and lie underneath it. Grab the bar with an overhand grip, slightly wider than shoulder-width apart. Position your body so that your heels are on the ground and your body is straight. Pull your chest up towards the bar by squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca una barra a la altura de la cintura y túmbate debajo de ella. Agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros. Coloca el cuerpo de manera que los talones queden en el suelo y el cuerpo esté recto. Tira del pecho hacia arriba en dirección a la barra apretando los omóplatos entre sí. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/2300-VPPtusI.jpg', 'videos/2300-VPPtusI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2298', 'inverted row on bench', 'back', 'back', 'body weight', 'Set up a bench at a height that allows your body to hang freely underneath it. Lie face up on the ground with your head towards the bench. Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart. Position your body so that your heels are on the ground and your arms are fully extended. Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench. Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca un banco a una altura que permita que el cuerpo cuelgue libremente debajo de él. Túmbate boca arriba en el suelo con la cabeza hacia el banco. Estira los brazos hacia arriba y agarra el banco con agarre prono, ligeramente más ancho que la altura de los hombros. Coloca el cuerpo de manera que los talones queden en el suelo y los brazos completamente extendidos. Activa el core y aprieta los omóplatos entre sí mientras tiras del pecho hacia el banco. Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/2298-Mxa7Cr8.jpg', 'videos/2298-Mxa7Cr8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0497', 'inverted row v. 2', 'back', 'back', 'body weight', 'Set up a bar at waist height on a Smith machine or use a suspension trainer. Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart. Walk your feet forward, leaning back until your body is at a slight angle. Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Coloca una barra a la altura de la cintura en una máquina Smith o usa un entrenador de suspensión. Ponte de pie frente a la barra o al entrenador de suspensión y agárrala con agarre prono, manos separadas a la altura de los hombros. Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en un ligero ángulo. Mantén el cuerpo recto y tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0497-uX3sUBz.jpg', 'videos/0497-uX3sUBz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0498', 'inverted row with straps', 'back', 'back', 'body weight', 'Set up a suspension trainer or straps at chest height. Stand facing the anchor point and grab the handles with an overhand grip. Walk your feet forward, leaning back until your body is at an angle. Keep your body straight and engage your core. Pull your chest towards the handles, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower yourself back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un entrenador de suspensión o correas a la altura del pecho. Ponte de pie frente al punto de anclaje y agarra las asas con agarre prono. Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en ángulo. Mantén el cuerpo recto y activa el core. Tira del pecho hacia las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0498-jdiExfW.jpg', 'videos/0498-jdiExfW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1419', 'iron cross stretch', 'upper legs', 'upper legs', 'body weight', 'Lie flat on your back with your arms extended out to the sides. Raise your legs up towards the ceiling, keeping them straight. Slowly lower your legs to one side, aiming to touch the floor with your feet. Hold the stretch for a few seconds, then return your legs to the starting position. Repeat the stretch on the other side. Continue alternating sides for the desired number of repetitions.', 'Túmbate boca arriba con los brazos extendidos hacia los lados. Levanta las piernas hacia el techo, manteniéndolas rectas. Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies. Mantén el estiramiento durante unos segundos, luego regresa las piernas a la posición inicial. Repite el estiramiento en el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/1419-pZwUsKB.jpg', 'videos/1419-pZwUsKB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1297', 'isometric chest squeeze', 'chest', 'chest', 'body weight', 'Stand with your feet shoulder-width apart and your knees slightly bent. Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other. Squeeze your chest muscles together as hard as you can, while keeping your arms straight. Hold this position for a few seconds, focusing on contracting your chest muscles. Release the squeeze and relax your chest muscles. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos rectos frente a ti, paralelos al suelo, con las palmas una frente a la otra. Aprieta los músculos del pecho con la mayor fuerza posible, manteniendo los brazos rectos. Mantén esta posición durante unos segundos, concentrándote en contraer los músculos del pecho. Suelta la contracción y relaja los músculos del pecho. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1297-HbSG1Pw.jpg', 'videos/1297-HbSG1Pw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0500', 'isometric wipers', 'chest', 'chest', 'body weight', 'Start by lying flat on your back on a mat or bench. Extend your arms straight out to the sides, perpendicular to your body. Engage your core and lift both legs off the ground, keeping them together and straight. Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control. Pause for a moment, then use your core to lift your legs back to the starting position. Repeat the movement, this time lowering your legs to the opposite side. Continue alternating sides for the desired number of repetitions.', 'Comienza acostado boca arriba en una esterilla o un banco. Extiende los brazos hacia los lados, perpendiculares al cuerpo. Activa el core y levanta ambas piernas del suelo, manteniéndolas juntas y rectas. Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies mientras mantienes el control. Haz una pausa breve, luego usa el core para llevar las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez bajando las piernas hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps","core"]'::jsonb, 'pectorals', 'images/0500-11wrviz.jpg', 'videos/0500-11wrviz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0501', 'jack burpee', 'cardio', 'cardio', 'body weight', 'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position, placing your hands on the ground in front of you. Kick your feet back, landing in a push-up position. Perform a push-up, lowering your chest to the ground and then pushing back up. Jump your feet forward, landing in a squat position. Jump up explosively, reaching your arms overhead. Land softly and immediately lower back into the squat position to begin the next repetition.', 'Comienza de pie con los pies separados a la altura de los hombros. Baja el cuerpo a una posición de sentadilla, colocando las manos en el suelo frente a ti. Lanza los pies hacia atrás, aterrizando en posición de flexión de brazos. Realiza una flexión de brazos, bajando el pecho hacia el suelo y luego empujando de nuevo hacia arriba. Salta con los pies hacia adelante, aterrizando en posición de sentadilla. Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza. Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.', 'quadriceps', '["quadriceps","hamstrings","calves","shoulders","triceps","core"]'::jsonb, 'cardiovascular system', 'images/0501-mr7pkqP.jpg', 'videos/0501-mr7pkqP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3224', 'jack jump (male)', 'cardio', 'cardio', 'body weight', 'Stand with your feet together and your arms by your sides. Jump up, spreading your feet apart and raising your arms above your head. As you land, quickly jump back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies juntos y los brazos a los costados. Salta, separando los pies y levantando los brazos por encima de la cabeza. Al aterrizar, salta rápidamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","calves"]'::jsonb, 'cardiovascular system', 'images/3224-1g5bPpA.jpg', 'videos/3224-1g5bPpA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0507', 'jackknife sit-up', 'waist', 'waist', 'body weight', 'Lie flat on your back with your legs extended and your arms overhead. Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes. Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba con las piernas extendidas y los brazos por encima de la cabeza. Activa el core y levanta las piernas y la parte superior del cuerpo al mismo tiempo, llevando las manos hacia los dedos de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0507-mbkgB44.jpg', 'videos/0507-mbkgB44.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0508', 'janda sit-up', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0508-1GPHRyK.jpg', 'videos/0508-1GPHRyK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2612', 'jump rope', 'cardio', 'cardio', 'rope', 'Hold the handles of the jump rope with your hands, palms facing inward. Stand with your feet shoulder-width apart and knees slightly bent. Swing the rope over your head and jump over it as it comes towards your feet. Land softly on the balls of your feet and repeat the jump as the rope comes around again. Continue jumping for the desired duration or number of repetitions.', 'Sujeta las asas de la cuerda de saltar con las manos, palmas hacia adentro. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Balancea la cuerda por encima de la cabeza y salta sobre ella cuando se acerque a los pies. Aterriza suavemente sobre la punta de los pies y repite el salto cuando la cuerda vuelva a pasar. Continúa saltando durante el tiempo o el número de repeticiones deseado.', 'calves', '["calves","quadriceps","hamstrings","glutes"]'::jsonb, 'cardiovascular system', 'images/2612-e1e76I2.jpg', 'videos/2612-e1e76I2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0514', 'jump squat', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and pushing your hips back. Jump explosively off the ground, extending your hips, knees, and ankles. While in mid-air, quickly bring your arms forward for balance. Land softly on the balls of your feet and immediately go into the next repetition. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta de forma explosiva desde el suelo, extendiendo las caderas, las rodillas y los tobillos. Mientras estás en el aire, lleva rápidamente los brazos hacia adelante para mantener el equilibrio. Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0514-LIlE5Tn.jpg', 'videos/0514-LIlE5Tn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0513', 'jump squat v. 2', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and pushing your hips back. Jump explosively, extending your hips and knees fully. Land softly on the balls of your feet and immediately lower your body back into a squat position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta de forma explosiva, extendiendo por completo las caderas y las rodillas. Aterriza suavemente sobre la punta de los pies y de inmediato baja el cuerpo de nuevo a una posición de sentadilla. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0513-TDYiji6.jpg', 'videos/0513-TDYiji6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0517', 'kettlebell advanced windmill', 'waist', 'waist', 'kettlebell', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward. Rotate your left foot slightly to the right, and shift your weight onto your left leg. Bend your left knee and hinge at the hip, lowering your torso towards the left side. Keep your right arm extended overhead and your eyes on the kettlebell. As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly. Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground. Pause for a moment, then engage your core and push through your left heel to return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sostén una pesa rusa en la mano derecha, con el brazo extendido por encima de la cabeza y la palma hacia adelante. Gira el pie izquierdo ligeramente hacia la derecha y traslada el peso hacia la pierna izquierda. Dobla la rodilla izquierda y flexiona la cadera, bajando el torso hacia el lado izquierdo. Mantén el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa. Mientras bajas el torso, permite que la pierna derecha se enderece y que el pie derecho gire ligeramente. Baja el torso hasta sentir un estiramiento en el isquiotibial izquierdo y que el brazo derecho apunte hacia el suelo. Haz una pausa breve, luego activa el core y empuja con el talón izquierdo para regresar a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'obliques', '["obliques","shoulders"]'::jsonb, 'abs', 'images/0517-Kal9cQQ.jpg', 'videos/0517-Kal9cQQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0518', 'kettlebell alternating hang clean', 'lower arms', 'lower arms', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Allow the kettlebells to hang in front of your body with your arms fully extended. In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders. As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms. Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm. Continue alternating arms for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que las pesas rusas cuelguen frente al cuerpo con los brazos completamente extendidos. En un solo movimiento fluido, extiende las caderas de forma explosiva, encoge los hombros y tira de las pesas rusas hacia los hombros. Cuando las pesas rusas alcancen la altura de los hombros, gira las muñecas y atrápalas en posición de descanso, con las palmas hacia adentro y las pesas rusas apoyadas en la parte externa de los antebrazos. Baja las pesas rusas de nuevo a la posición inicial y repite el movimiento con el brazo opuesto. Continúa alternando los brazos durante el número de repeticiones deseado.', 'shoulders', '["shoulders","traps","core"]'::jsonb, 'forearms', 'images/0518-I4tibZG.jpg', 'videos/0518-I4tibZG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0520', 'kettlebell alternating press', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Press one kettlebell overhead, fully extending your arm. Lower the kettlebell back to shoulder height. Repeat with the other arm. Continue alternating arms for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Empuja una pesa rusa por encima de la cabeza, extendiendo el brazo por completo. Baja la pesa rusa de nuevo a la altura de los hombros. Repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0520-5KLbZWx.jpg', 'videos/0520-5KLbZWx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0519', 'kettlebell alternating press on floor', 'chest', 'chest', 'kettlebell', 'Start by lying on your back on the floor with your knees bent and feet flat on the ground. Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling. Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up. Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder. Continue alternating the press motion with each kettlebell for the desired number of repetitions.', 'Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo. Sostén una pesa rusa en cada mano, con las palmas hacia los pies y los brazos extendidos rectos hacia el techo. Baja una pesa rusa hacia el hombro mientras mantienes la otra pesa rusa extendida recta hacia arriba. Empuja la pesa rusa bajada de vuelta hacia la posición inicial mientras al mismo tiempo bajas la otra pesa rusa hacia el hombro. Continúa alternando el movimiento de empuje con cada pesa rusa durante el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0519-7w6i0vE.jpg', 'videos/0519-7w6i0vE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0521', 'kettlebell alternating renegade row', 'back', 'back', 'kettlebell', 'Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart. Engage your core and keep your body in a straight line from head to heels. Pull one kettlebell up towards your chest, keeping your elbow close to your body. Lower the kettlebell back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos sujetando las pesas rusas y los pies separados a la altura de las caderas. Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones. Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo. Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'core', '["core","shoulders"]'::jsonb, 'upper back', 'images/0521-b9kqlBy.jpg', 'videos/0521-b9kqlBy.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0522', 'kettlebell alternating row', 'back', 'back', 'kettlebell', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body. Bend forward at the hips, keeping your back straight and your core engaged. Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Lower the kettlebell back down to the starting position and repeat with the other arm. Continue alternating arms for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y apretando los omóplatos entre sí. Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0522-Ca76jUE.jpg', 'videos/0522-Ca76jUE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0523', 'kettlebell arnold press', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you. Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms. Pause at the top of the movement, then slowly lower the kettlebells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros con las palmas hacia ti. Activa el core y empuja las pesas rusas por encima de la cabeza, girando las palmas hacia adelante mientras extiendes los brazos. Haz una pausa en la parte superior del movimiento, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0523-UM8mgyG.jpg', 'videos/0523-UM8mgyG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0524', 'kettlebell bent press', 'waist', 'waist', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in your right hand. Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked. Rotate your torso to the left, shifting your weight onto your left foot. Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead. As you lower, keep your eyes on the kettlebell and your chest lifted. Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward. As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha. Dobla ligeramente las rodillas y empuja la pesa rusa por encima de la cabeza con el brazo derecho, manteniendo el codo bloqueado. Rota el torso hacia la izquierda, trasladando tu peso al pie izquierdo. Flexiona la rodilla izquierda y baja el torso hacia el suelo, manteniendo el brazo derecho extendido por encima de la cabeza. Mientras bajas, mantén la mirada en la pesa rusa y el pecho elevado. Cuando tu mano izquierda toque el suelo, empuja con el pie izquierdo y estira la pierna izquierda, llevando las caderas hacia adelante. Mientras llevas las caderas hacia adelante, usa el core y el brazo derecho para empujar la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'shoulders', '["shoulders","triceps","obliques"]'::jsonb, 'abs', 'images/0524-kjE55n5.jpg', 'videos/0524-kjE55n5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0525', 'kettlebell bottoms up clean from the hang position', 'upper arms', 'upper arms', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Allow the kettlebell to hang down between your legs, with your arm fully extended. In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder. As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up. Catch the kettlebell at shoulder height with your elbow bent and your palm facing up. Lower the kettlebell back down to the starting position by reversing the movement. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que la pesa rusa cuelgue entre tus piernas, con el brazo completamente extendido. En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras tiras de la pesa rusa hacia el hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca de modo que la base de la pesa rusa quede hacia arriba. Atrapa la pesa rusa a la altura del hombro con el codo flexionado y la palma hacia arriba. Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado, luego cambia de lado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/0525-4KJEpzb.jpg', 'videos/0525-4KJEpzb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0526', 'kettlebell double alternating hang clean', 'upper arms', 'upper arms', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up. Allow the kettlebells to hang straight down in front of your body. In one fluid motion, explosively extend your hips and knees while shrugging your shoulders. As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides. Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward. Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Deja que las pesas rusas cuelguen rectas frente a tu cuerpo. En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras encoges los hombros. Mientras las pesas rusas suben, tira de ellas hacia los hombros, manteniendo los codos altos y hacia los lados. Atrapa las pesas rusas a la altura del hombro, con las palmas hacia adentro y los codos apuntando hacia adelante. Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'biceps', 'images/0526-a4F9Oyc.jpg', 'videos/0526-a4F9Oyc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0527', 'kettlebell double jerk', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Bend your knees slightly and engage your core. Press the kettlebells overhead, fully extending your arms. Bend your knees and quickly drop into a partial squat. Explosively extend your hips and knees, driving the kettlebells overhead. Lock out your arms and catch the kettlebells overhead with your knees slightly bent. Stand up straight and return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Flexiona ligeramente las rodillas y activa el core. Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Flexiona las rodillas y baja rápidamente a una sentadilla parcial. Extiende explosivamente las caderas y las rodillas, impulsando las pesas rusas hacia arriba. Bloquea los brazos y atrapa las pesas rusas por encima de la cabeza con las rodillas ligeramente flexionadas. Ponte de pie recto y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0527-tznL2Ad.jpg', 'videos/0527-tznL2Ad.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0528', 'kettlebell double push press', 'shoulders', 'shoulders', 'kettlebell', 'Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Bend your knees slightly and engage your core. Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead. As the kettlebells reach the top, press them fully overhead, locking out your arms. Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Inicia el movimiento extendiendo explosivamente las caderas, las rodillas y los tobillos, impulsando las pesas rusas por encima de la cabeza. Cuando las pesas rusas lleguen arriba, presiónalas completamente por encima de la cabeza, bloqueando los brazos. Baja las pesas rusas a la posición inicial flexionando los codos y llevándolas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0528-I4KkPdl.jpg', 'videos/0528-I4KkPdl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0529', 'kettlebell double snatch', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs. Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up. In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders. As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms. Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano con el brazo extendido frente a los muslos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. En un solo movimiento explosivo, extiende las caderas, las rodillas y los tobillos, y al mismo tiempo tira de las pesas rusas hacia los hombros. Cuando las pesas rusas lleguen a la altura del hombro, rota las muñecas y lanza las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'trapezius', '["trapezius","forearms","core"]'::jsonb, 'delts', 'images/0529-M74kdvm.jpg', 'videos/0529-M74kdvm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0530', 'kettlebell double windmill', 'waist', 'waist', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in your right hand. Extend your right arm overhead, keeping your eyes on the kettlebell. Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right. Bend at the waist to the left, keeping your right arm extended overhead. Lower the kettlebell towards the ground, reaching towards your left foot. Pause for a moment, then engage your core and push through your right foot to return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha. Extiende el brazo derecho por encima de la cabeza, manteniendo la mirada en la pesa rusa. Rota el pie izquierdo 45 grados hacia la izquierda y el pie derecho 90 grados hacia la derecha. Flexiona la cintura hacia la izquierda, manteniendo el brazo derecho extendido por encima de la cabeza. Baja la pesa rusa hacia el suelo, extendiéndote hacia el pie izquierdo. Haz una pausa breve, luego activa el core y empuja con el pie derecho para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'shoulders', '["shoulders","hamstrings"]'::jsonb, 'abs', 'images/0530-OaE7CpD.jpg', 'videos/0530-OaE7CpD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0531', 'kettlebell extended range one arm press on floor', 'chest', 'chest', 'kettlebell', 'Start by lying on your back on the floor with your knees bent and feet flat on the ground. Hold a kettlebell in one hand, with your palm facing towards your feet. Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight. Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions, then switch to the other arm.', 'Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo. Sujeta una pesa rusa con una mano, con la palma hacia los pies. Extiende el brazo recto hacia el techo, manteniendo el codo bloqueado y la muñeca recta. Baja lentamente la pesa rusa de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0531-rseLfH3.jpg', 'videos/0531-rseLfH3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0532', 'kettlebell figure 8', 'waist', 'waist', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Pass the kettlebell between your legs, switching hands as it reaches the back of your legs. As the kettlebell comes forward, pass it to the other hand between your legs. Continue passing the kettlebell between your legs in a figure 8 motion. Maintain a steady pace and engage your core throughout the exercise. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Pasa la pesa rusa entre las piernas, cambiándola de mano cuando llegue detrás de las piernas. Cuando la pesa rusa vuelva hacia adelante, pásala a la otra mano entre las piernas. Continúa pasando la pesa rusa entre las piernas con un movimiento en forma de ocho. Mantén un ritmo constante y activa el core durante todo el ejercicio. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","forearms"]'::jsonb, 'abs', 'images/0532-L4ay0PW.jpg', 'videos/0532-L4ay0PW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0533', 'kettlebell front squat', 'upper legs', 'upper legs', 'kettlebell', 'Stand with your feet shoulder-width apart, toes slightly turned out. Hold the kettlebell with both hands in front of your chest, close to your body. Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Drive through your heels to stand back up, squeezing your glutes at the top. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la pesa rusa con ambas manos frente al pecho, cerca del cuerpo. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0533-DB0n8AG.jpg', 'videos/0533-DB0n8AG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0534', 'kettlebell goblet squat', 'upper legs', 'upper legs', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands. Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa cerca del pecho con ambas manos. Manteniendo el pecho elevado y el core activado, baja el cuerpo a una posición de sentadilla flexionando las rodillas y las caderas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0534-ZA8b5hc.jpg', 'videos/0534-ZA8b5hc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0535', 'kettlebell hang clean', 'upper legs', 'upper legs', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower the kettlebell towards the ground, allowing it to swing between your legs. Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height. As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm. Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja la pesa rusa hacia el suelo, dejando que se balancee entre las piernas. Extiende rápidamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro. Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con el codo pegado al cuerpo y la pesa rusa apoyada en el antebrazo. Baja la pesa rusa de vuelta a la posición inicial entre las piernas y repite el número de repeticiones deseado.', 'glutes', '["glutes","quadriceps","calves"]'::jsonb, 'hamstrings', 'images/0535-LHWF7us.jpg', 'videos/0535-LHWF7us.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0536', 'kettlebell lunge pass through', 'upper legs', 'upper legs', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands. Take a step forward with your right foot, lowering your body into a lunge position. As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand. Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand. Repeat the lunge on the opposite side, passing the kettlebell under your left thigh. Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mientras avanzas en la zancada, pasa la pesa rusa por debajo del muslo derecho y trasládala a la mano izquierda. Empuja con el pie derecho para volver a la posición inicial, mientras pasas la pesa rusa de vuelta a la mano derecha al mismo tiempo. Repite la zancada en el lado opuesto, pasando la pesa rusa por debajo del muslo izquierdo. Continúa alternando zancadas y pasando la pesa rusa entre las manos durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0536-WKMQzCD.jpg', 'videos/0536-WKMQzCD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0537', 'kettlebell one arm clean and jerk', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip. Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs. Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height. As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas y inclínate desde las caderas, bajando la pesa rusa entre las piernas. Extiende explosivamente las caderas, las rodillas y los tobillos, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca y lanza la mano recta hacia arriba, bloqueando el brazo por encima de la cabeza. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0537-vzAxBtt.jpg', 'videos/0537-vzAxBtt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1298', 'kettlebell one arm floor press', 'chest', 'chest', 'kettlebell', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground. Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling. Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body. Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow. Repeat for the desired number of repetitions, then switch to the other arm.', 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la pesa rusa con una mano con la palma hacia los pies y el brazo extendido recto hacia el techo. Baja lentamente la pesa rusa hacia el pecho flexionando el codo, manteniendo el brazo superior cerca del cuerpo. Haz una pausa cuando la pesa rusa esté justo encima del pecho, luego empújala de vuelta hacia arriba a la posición inicial extendiendo el codo. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1298-rg59QCH.jpg', 'videos/1298-rg59QCH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0538', 'kettlebell one arm jerk', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height. Bend your knees slightly and engage your core. Press the kettlebell overhead in a straight line, fully extending your arm. As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum. As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips. Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead. Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead. Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Presiona la pesa rusa por encima de la cabeza en línea recta, extendiendo el brazo por completo. Mientras presionas la pesa rusa por encima de la cabeza, flexiona las rodillas simultáneamente y estíralas rápidamente para generar impulso. Cuando la pesa rusa llegue a su punto más alto, baja rápidamente por debajo de ella flexionando las rodillas y las caderas. Atrapa la pesa rusa con una ligera flexión de rodillas y caderas, y el brazo completamente extendido por encima de la cabeza. Ponte de pie recto, extendiendo por completo las rodillas y las caderas, y estabiliza la pesa rusa por encima de la cabeza. Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y las caderas, y repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0538-S37C94C.jpg', 'videos/0538-S37C94C.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0539', 'kettlebell one arm military press to the side', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height. Engage your core and keep your back straight. Press the kettlebell overhead, extending your arm fully. Pause for a moment at the top, then slowly lower the kettlebell back to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Activa el core y mantén la espalda recta. Presiona la pesa rusa por encima de la cabeza, extendiendo el brazo por completo. Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0539-yCvYdi7.jpg', 'videos/0539-yCvYdi7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0540', 'kettlebell one arm push press', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level. Bend your knees slightly and engage your core. Press the kettlebell overhead by extending your arm and fully extending your legs. Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro. Flexiona ligeramente las rodillas y activa el core. Presiona la pesa rusa por encima de la cabeza extendiendo el brazo y estirando por completo las piernas. Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y devolviendo la pesa rusa al hombro. Repite el número de repeticiones deseado, luego cambia de lado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0540-osdXT3K.jpg', 'videos/0540-osdXT3K.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0541', 'kettlebell one arm row', 'back', 'back', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged. Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position. Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0541-g9AsZ8P.jpg', 'videos/0541-g9AsZ8P.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0542', 'kettlebell one arm snatch', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs. Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground. Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder. As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm. Lower the kettlebell back down between your legs and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano entre las piernas. Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo. Extiende explosivamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hacia el hombro. Cuando la pesa rusa llegue a la altura del hombro, rota la mano y lánzala recta hacia arriba por encima de la cabeza, extendiendo el brazo por completo. Baja la pesa rusa de vuelta entre las piernas y repite el número de repeticiones deseado.', 'trapezius', '["trapezius","forearms","core"]'::jsonb, 'delts', 'images/0542-aXcUyKb.jpg', 'videos/0542-aXcUyKb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0543', 'kettlebell pirate supper legs', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise the kettlebell up to shoulder height, keeping your elbow close to your body. Extend your arm fully overhead, straightening your elbow. Lower the kettlebell back down to shoulder height, then return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta la pesa rusa hasta la altura del hombro, manteniendo el codo cerca del cuerpo. Extiende el brazo por completo por encima de la cabeza, enderezando el codo. Baja la pesa rusa de vuelta a la altura del hombro, luego vuelve a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'triceps', '["triceps","forearms"]'::jsonb, 'delts', 'images/0543-kuXhl0o.jpg', 'videos/0543-kuXhl0o.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0544', 'kettlebell pistol squat', 'upper legs', 'upper legs', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands. Lift your left foot off the ground and extend it forward, keeping it parallel to the ground. Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended. Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos. Levanta el pie izquierdo del suelo y extiéndelo hacia adelante, manteniéndolo paralelo al suelo. Baja lentamente el cuerpo a una posición de sentadilla, manteniendo el pie derecho plano en el suelo y la pierna izquierda extendida. Haz una pausa breve en la parte baja de la sentadilla, luego empuja con el talón derecho para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0544-5bpPTHv.jpg', 'videos/0544-5bpPTHv.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0545', 'kettlebell plyo push-up', 'chest', 'chest', 'kettlebell', 'Start in a high plank position with your hands on the kettlebells, shoulder-width apart. Lower your chest towards the ground, keeping your elbows close to your body. Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully. Land softly back on the kettlebells and immediately lower your chest back down for the next repetition. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos sobre las pesas rusas, separadas a la altura de los hombros. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. Empuja con las manos de forma explosiva, levantándolas de las pesas rusas y extendiendo los brazos por completo. Aterriza suavemente sobre las pesas rusas y baja el pecho de inmediato para la siguiente repetición. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0545-ktf3nvW.jpg', 'videos/0545-ktf3nvW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0546', 'kettlebell seated press', 'shoulders', 'shoulders', 'kettlebell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a kettlebell in each hand at shoulder height, palms facing forward. Press the kettlebells overhead, fully extending your arms. Lower the kettlebells back to shoulder height. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una pesa rusa en cada mano a la altura del hombro, con las palmas hacia adelante. Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Baja las pesas rusas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0546-BkxB8LW.jpg', 'videos/0546-BkxB8LW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1438', 'kettlebell seated two arm military press', 'shoulders', 'shoulders', 'kettlebell', 'Sit on a bench with your back straight and feet flat on the ground. Hold a kettlebell in each hand at shoulder level with your palms facing forward. Press the kettlebells overhead by extending your arms fully. Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level. Repeat for the desired number of repetitions.', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante. Presiona las pesas rusas por encima de la cabeza extendiendo los brazos por completo. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/1438-ZEkjZDi.jpg', 'videos/1438-ZEkjZDi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0547', 'kettlebell seesaw press', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Press one kettlebell overhead while keeping the other kettlebell at shoulder height. Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead. Continue alternating the pressing motion, creating a seesaw-like movement. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros. Presiona una pesa rusa por encima de la cabeza mientras mantienes la otra pesa rusa a la altura del hombro. Baja la pesa rusa presionada de vuelta a la altura del hombro mientras presionas simultáneamente la otra pesa rusa por encima de la cabeza. Continúa alternando el movimiento de presión, creando un movimiento similar a un balancín. Repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/0547-UDm6cGl.jpg', 'videos/0547-UDm6cGl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0548', 'kettlebell sumo high pull', 'back', 'back', 'kettlebell', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards. Hold a kettlebell with both hands in front of your body, arms extended downwards. Bend your knees and lower your hips into a squat position, keeping your back straight. Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin. As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera. Sujeta una pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos hacia abajo. Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta. Empuja con los talones y extiende explosivamente las caderas y las rodillas, tirando de la pesa rusa hacia la barbilla. Mientras tiras de la pesa rusa hacia arriba, mantén los codos altos y abiertos, y junta los omóplatos. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'shoulders', '["shoulders","glutes","hamstrings"]'::jsonb, 'traps', 'images/0548-8ARQ9Hw.jpg', 'videos/0548-8ARQ9Hw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0549', 'kettlebell swing', 'upper legs', 'upper legs', 'kettlebell', 'Stand with your feet shoulder-width apart, toes pointed slightly outward. Hold the kettlebell with both hands in front of your body, arms extended. Bend your knees slightly and hinge at the hips, pushing your butt back. Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back. Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips. Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos. Flexiona ligeramente las rodillas e inclínate desde las caderas, empujando los glúteos hacia atrás. Lleva la pesa rusa hacia atrás entre las piernas, manteniendo los brazos rectos y la espalda plana. Lleva las caderas hacia adelante y haz que la pesa rusa suba hasta la altura del hombro, usando el impulso generado por las caderas. Deja que la pesa rusa se balancee de vuelta hacia abajo entre las piernas y repite el movimiento el número de repeticiones deseado.', 'hamstrings', '["hamstrings","core"]'::jsonb, 'glutes', 'images/0549-UHJlbu3.jpg', 'videos/0549-UHJlbu3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0550', 'kettlebell thruster', 'shoulders', 'shoulders', 'kettlebell', 'Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other. Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight. As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead. Lock out your arms at the top of the movement, fully extending your elbows. Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos, con las palmas una frente a la otra. Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás, manteniendo el pecho elevado y la espalda recta. Al llegar a la parte baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando al mismo tiempo la pesa rusa por encima de la cabeza. Bloquea los brazos en la parte alta del movimiento, extendiendo los codos por completo. Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento, flexionando los codos y bajando el peso de vuelta al pecho. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","glutes","core"]'::jsonb, 'delts', 'images/0550-yWxMvB5.jpg', 'videos/0550-yWxMvB5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0551', 'kettlebell turkish get up (squat style)', 'upper legs', 'upper legs', 'kettlebell', 'Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder. Bend your right knee and place your right foot flat on the ground, keeping your left leg extended. Pressing through your right foot, lift your hips off the ground, coming into a bridge position. Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground. Rotate your torso to the left, bringing your left hand to the ground for support. Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position. From the kneeling position, stand up, keeping the kettlebell extended overhead. Reverse the movement to return to the starting position. Repeat the exercise on the other side, starting with the kettlebell in your left hand.', 'Comienza tumbado boca arriba con las piernas extendidas y la pesa rusa sostenida en la mano derecha, con el brazo completamente extendido por encima del hombro. Flexiona la rodilla derecha y coloca el pie derecho plano en el suelo, manteniendo la pierna izquierda extendida. Presionando con el pie derecho, levanta las caderas del suelo, llegando a una posición de puente. Desliza la pierna izquierda por debajo del cuerpo, flexionando la rodilla izquierda y colocando el pie izquierdo plano en el suelo. Rota el torso hacia la izquierda, llevando la mano izquierda al suelo como apoyo. Presionando con el pie derecho y la mano izquierda, levanta el torso del suelo, llegando a una posición de rodillas. Desde la posición de rodillas, ponte de pie, manteniendo la pesa rusa extendida por encima de la cabeza. Invierte el movimiento para volver a la posición inicial. Repite el ejercicio en el otro lado, comenzando con la pesa rusa en la mano izquierda.', 'quadriceps', '["quadriceps","hamstrings","core"]'::jsonb, 'glutes', 'images/0551-Ha7SZ3y.jpg', 'videos/0551-Ha7SZ3y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0552', 'kettlebell two arm clean', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you. Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground. Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders. As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm. Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos con ambas manos, con las palmas hacia ti. Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo. Extiende explosivamente las caderas y las rodillas, usando el impulso para tirar de la pesa rusa hacia los hombros. Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con los codos pegados al cuerpo y la pesa rusa apoyada en la parte posterior del antebrazo. Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'traps', '["traps","forearms"]'::jsonb, 'delts', 'images/0552-7Ba7bQ2.jpg', 'videos/0552-7Ba7bQ2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0553', 'kettlebell two arm military press', 'shoulders', 'shoulders', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward. Engage your core and press the kettlebells overhead, fully extending your arms. Pause for a moment at the top, then slowly lower the kettlebells back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante. Activa el core y presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0553-blBXysN.jpg', 'videos/0553-blBXysN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1345', 'kettlebell two arm row', 'back', 'back', 'kettlebell', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body. Bend forward at the hips, keeping your back straight and your core engaged. Pull the kettlebells up towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de las pesas rusas hacia el pecho, juntando los omóplatos. Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1345-wf24o8S.jpg', 'videos/1345-wf24o8S.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0554', 'kettlebell windmill', 'waist', 'waist', 'kettlebell', 'Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead. Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward. Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell. Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side. Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques. Repeat for the desired number of repetitions, then switch sides.', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en la mano derecha por encima de la cabeza. Rota el pie izquierdo hacia afuera unos 45 grados y mantén el pie derecho apuntando hacia adelante. Inclina el torso hacia el lado izquierdo, manteniendo el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa. Baja el torso tanto como puedas mientras mantienes el brazo derecho recto y el brazo izquierdo extendido hacia el lado. Haz una pausa breve, luego vuelve a la posición inicial empujando con el pie derecho y activando los oblicuos. Repite el número de repeticiones deseado, luego cambia de lado.', 'obliques', '["obliques","shoulders"]'::jsonb, 'abs', 'images/0554-9Tkqa9O.jpg', 'videos/0554-9Tkqa9O.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0555', 'kick out sit', 'upper legs', 'upper legs', 'body weight', 'Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle. Lean back slightly and place your hands on the edge of the bench or chair for support. Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you. Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco o una silla con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Inclínate ligeramente hacia atrás y coloca las manos en el borde del banco o la silla como apoyo. Activando los isquiotibiales, levanta los pies del suelo y extiende las piernas rectas hacia adelante. Haz una pausa breve en lo alto, luego flexiona lentamente las rodillas y lleva los pies de vuelta hacia el cuerpo. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","glutes"]'::jsonb, 'hamstrings', 'images/0555-v7p5bYl.jpg', 'videos/0555-v7p5bYl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0558', 'kipping muscle up', 'back', 'back', 'body weight', 'Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart. Engage your core and use a swinging motion to generate momentum. As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement. Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms. Lower yourself back down to the starting position by bending your arms and controlling the descent. Repeat for the desired number of repetitions.', 'Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Activa el core y usa un movimiento de balanceo para generar impulso. Mientras te balanceas hacia adelante, tira del pecho hacia la barra, usando los dorsales y los bíceps para iniciar el movimiento. Continúa el movimiento ascendente hasta que el pecho llegue a la barra, luego pasa a una posición de fondos empujando hacia abajo en la barra y extendiendo los brazos. Bájate de vuelta a la posición inicial flexionando los brazos y controlando el descenso. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps","shoulders","core"]'::jsonb, 'lats', 'images/0558-pM07UxU.jpg', 'videos/0558-pM07UxU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3640', 'knee touch crunch', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee. Return to the starting position and repeat, this time reaching your left hand towards your right knee. Continue alternating sides for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta los omóplatos del suelo y extiende la mano derecha hacia la rodilla izquierda. Vuelve a la posición inicial y repite, esta vez extendiendo la mano izquierda hacia la rodilla derecha. Continúa alternando lados durante el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/3640-dTg95eZ.jpg', 'videos/3640-dTg95eZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1420', 'kneeling jump squat', 'upper legs', 'upper legs', 'barbell', 'Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward. Hold a barbell across your upper back, resting it on your shoulders. Engage your core and glutes, then explosively jump up into the air, extending your hips and knees. As you jump, push through your toes and fully extend your ankles, knees, and hips. Land softly back on the ground, bending your knees to absorb the impact. Immediately go into the next repetition, repeating the jump squat motion.', 'Comienza arrodillado en el suelo con los pies separados a la altura de las caderas y los dedos de los pies apuntando hacia adelante. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros. Activa el core y los glúteos, luego salta explosivamente hacia arriba, extendiendo las caderas y las rodillas. Mientras saltas, empuja con los dedos de los pies y extiende por completo los tobillos, las rodillas y las caderas. Aterriza suavemente de vuelta en el suelo, flexionando las rodillas para absorber el impacto. Pasa de inmediato a la siguiente repetición, repitiendo el movimiento de sentadilla con salto.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1420-UgDm3oy.jpg', 'videos/1420-UgDm3oy.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1346', 'kneeling lat stretch', 'back', 'back', 'body weight', 'Kneel on the ground with your knees hip-width apart and your toes pointing back. Extend your arms overhead and interlace your fingers. Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle. Hold the stretch for 20-30 seconds, then return to the starting position. Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle. Continue alternating sides for the desired number of repetitions.', 'Arrodíllate en el suelo con las rodillas separadas a la altura de las caderas y los dedos de los pies apuntando hacia atrás. Extiende los brazos por encima de la cabeza y entrelaza los dedos. Manteniendo la espalda recta, inclínate lentamente hacia el lado derecho, sintiendo un estiramiento en el dorsal izquierdo. Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial. Repite el estiramiento en el lado izquierdo, inclinándote hacia la izquierda y sintiendo un estiramiento en el dorsal derecho. Continúa alternando lados durante el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'lats', 'images/1346-f38OEuO.jpg', 'videos/1346-f38OEuO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3239', 'kneeling plank tap shoulder (male)', 'waist', 'waist', 'body weight', 'Start in a kneeling position with your hands on the ground, shoulder-width apart. Extend your legs behind you, resting on your toes, and lift your body into a plank position. Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder. Return the hand to the ground and repeat with the other hand. Continue alternating sides for the desired number of repetitions.', 'Comienza en posición de rodillas con las manos en el suelo, separadas a la altura de los hombros. Extiende las piernas hacia atrás, apoyándote en los dedos de los pies, y levanta el cuerpo a una posición de plancha. Manteniendo el core activado y las caderas estables, levanta una mano del suelo y toca el hombro opuesto. Devuelve la mano al suelo y repite con la otra mano. Continúa alternando lados durante el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'abs', 'images/3239-h1ezqSu.jpg', 'videos/3239-h1ezqSu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3211', 'kneeling push-up (male)', 'chest', 'chest', 'body weight', 'Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward. Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels. Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides. Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Comienza arrodillado en el suelo con las manos separadas a la altura de los hombros, los dedos apuntando hacia adelante. Extiende las piernas hacia atrás, apoyándote en la punta de los pies, de modo que tu cuerpo forme una línea recta desde la cabeza hasta los talones. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Continúa bajando hasta que el pecho esté justo encima del suelo, luego empuja hacia arriba a la posición inicial enderezando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/3211-ZOuKWir.jpg', 'videos/3211-ZOuKWir.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3288', 'korean dips', 'chest', 'chest', 'body weight', 'Position yourself between two parallel bars with your arms extended and supporting your body weight. Lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Colócate entre dos barras paralelas con los brazos extendidos sosteniendo el peso de tu cuerpo. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/3288-rWoBmi5.jpg', 'videos/3288-rWoBmi5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3418', 'l-pull-up', 'back', 'back', 'body weight', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended and your body straight. Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate con los brazos completamente extendidos y el cuerpo recto. Activa los dorsales y los bíceps para llevar el cuerpo hacia arriba en dirección a la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/3418-d1GgzTU.jpg', 'videos/3418-d1GgzTU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3419', 'l-sit on floor', 'waist', 'waist', 'body weight', 'Sit on the floor with your legs extended in front of you. Place your hands on the floor beside your hips, fingers pointing forward. Engage your core and lift your legs off the ground, keeping them straight. Try to bring your legs parallel to the floor, forming an ''L'' shape with your body. Hold this position for as long as you can. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Coloca las manos en el suelo junto a las caderas, con los dedos apuntando hacia adelante. Activa el core y levanta las piernas del suelo, manteniéndolas rectas. Intenta llevar las piernas paralelas al suelo, formando una ''L'' con el cuerpo. Mantén esta posición durante el mayor tiempo posible. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/3419-UpWmA5E.jpg', 'videos/3419-UpWmA5E.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0562', 'landmine 180', 'waist', 'waist', 'barbell', 'Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest. Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip. As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder. Continue this twisting motion, alternating sides, for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente al pecho. Flexiona ligeramente las rodillas y rota el torso hacia la derecha, llevando la barra hacia la cadera derecha. Cuando llegues a la parte baja del movimiento, invierte rápidamente el movimiento y rota el torso hacia la izquierda, llevando la barra hacia arriba y a través del cuerpo en dirección al hombro izquierdo. Continúa este movimiento de giro, alternando lados, durante el número de repeticiones deseado.', 'obliques', '["obliques","quadriceps"]'::jsonb, 'abs', 'images/0562-QYysSLV.jpg', 'videos/0562-QYysSLV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3237', 'landmine lateral raise', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold the barbell with an overhand grip, resting it on the front of your shoulders. Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con un agarre prono, apoyándola en la parte delantera de los hombros. Manteniendo el core activado y la espalda recta, levanta la barra alejándola del cuerpo, elevándola hasta la altura del hombro. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","upper back"]'::jsonb, 'delts', 'images/3237-eXMFHww.jpg', 'videos/3237-eXMFHww.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3300', 'lean planche', 'waist', 'waist', 'body weight', 'Start in a push-up position with your hands shoulder-width apart and your body straight. Engage your core and slowly shift your weight forward, bringing your shoulders past your hands. Keep your elbows slightly bent and your body straight as you lean forward. Hold this position for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en una posición de flexión con las manos separadas a la altura de los hombros y el cuerpo recto. Activa el core y traslada lentamente el peso hacia adelante, llevando los hombros más allá de las manos. Mantén los codos ligeramente flexionados y el cuerpo recto mientras te inclinas hacia adelante. Mantén esta posición durante unos segundos, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest","triceps"]'::jsonb, 'abs', 'images/3300-LYJodFS.jpg', 'videos/3300-LYJodFS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2271', 'left hook. boxing', 'shoulders', 'shoulders', 'body weight', 'Stand with your feet shoulder-width apart and your knees slightly bent. Keep your left hand up to protect your face and your right hand by your chin. Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion. Twist your torso and engage your core muscles to generate power in the punch. Snap your arm back to the starting position and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Mantén la mano izquierda arriba para proteger el rostro y la mano derecha junto a la barbilla. Rota las caderas y pívota sobre el pie izquierdo mientras extiendes el brazo izquierdo hacia adelante con un movimiento de golpe. Gira el torso y activa los músculos del core para generar potencia en el golpe. Lleva el brazo rápidamente de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps","forearms"]'::jsonb, 'delts', 'images/2271-hoXt6wv.jpg', 'videos/2271-hoXt6wv.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0570', 'leg pull in flat bench', 'waist', 'waist', 'body weight', 'Sit on a flat bench with your legs extended straight out in front of you. Place your hands on the bench beside your hips for support. Engage your abs and lift your legs off the ground, bringing your knees towards your chest. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco plano con las piernas extendidas rectas hacia adelante. Coloca las manos en el banco junto a las caderas para mayor apoyo. Activa el abdomen y levanta las piernas del suelo, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0570-OyoZ3Pu.jpg', 'videos/0570-OyoZ3Pu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1576', 'leg up hamstring stretch', 'upper legs', 'upper legs', 'body weight', 'Lie flat on your back with your legs extended. Bend one knee and bring it towards your chest, holding onto your thigh or shin. Straighten your leg as much as possible while keeping it elevated. Hold the stretch for 20-30 seconds. Repeat with the other leg.', 'Túmbate boca arriba con las piernas extendidas. Flexiona una rodilla y llévala hacia el pecho, sujetándote del muslo o la espinilla. Endereza la pierna tanto como sea posible mientras la mantienes elevada. Mantén el estiramiento durante 20-30 segundos. Repite con la otra pierna.', 'glutes', '["glutes"]'::jsonb, 'hamstrings', 'images/1576-sU5BrfP.jpg', 'videos/1576-sU5BrfP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2287', 'lever alternate leg press', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the seat and foot platform of the leverage machine to your desired position. Sit on the machine with your back against the backrest and your feet on the foot platform. Place your hands on the handles or sides of the machine for stability. Push one foot against the foot platform, extending your leg until it is almost fully straight. Pause for a moment, then slowly bend your leg and return to the starting position. Repeat with the other leg. Continue alternating legs for the desired number of repetitions.', 'Ajusta el asiento y la plataforma para los pies de la máquina de palanca a la posición deseada. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la plataforma para los pies. Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad. Empuja un pie contra la plataforma para los pies, extendiendo la pierna hasta que esté casi completamente recta. Haz una pausa breve, luego flexiona lentamente la pierna y vuelve a la posición inicial. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'quads', 'images/2287-V07qpXy.jpg', 'videos/2287-V07qpXy.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0571', 'lever alternating narrow grip seated row', 'back', 'back', 'leverage machine', 'Adjust the seat height and footplate position to ensure proper alignment. Sit on the machine with your back straight and feet flat on the footplate. Grasp the handles with a narrow grip, palms facing each other. Keep your chest up and shoulders back throughout the exercise. Pull one handle towards your torso while keeping the other handle stationary. Squeeze your shoulder blades together at the end of the movement. Slowly return the handle to the starting position and repeat with the other side. Continue alternating sides for the desired number of repetitions.', 'Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta. Siéntate en la máquina con la espalda recta y los pies planos sobre la placa para los pies. Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra. Mantén el pecho elevado y los hombros hacia atrás durante todo el ejercicio. Tira de una asa hacia el torso mientras mantienes la otra asa inmóvil. Aprieta los omóplatos al final del movimiento. Devuelve lentamente el asa a la posición inicial y repite con el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0571-w2oRpuH.jpg', 'videos/0571-w2oRpuH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0572', 'lever assisted chin-up', 'back', 'back', 'leverage machine', 'Adjust the leverage machine to your desired resistance level. Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart. Hang with your arms fully extended, keeping your body straight. Engage your back muscles and pull your body up towards the handles, leading with your chest. Continue pulling until your chin is above the handles. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de palanca al nivel de resistencia deseado. Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Cuélgate con los brazos completamente extendidos, manteniendo el cuerpo recto. Activa los músculos de la espalda y tira del cuerpo hacia arriba en dirección a las asas, liderando con el pecho. Continúa subiendo hasta que la barbilla quede por encima de las agarraderas. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0572-MaMuGH6.jpg', 'videos/0572-MaMuGH6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0573', 'lever back extension', 'back', 'back', 'leverage machine', 'Adjust the machine to fit your body size and range of motion. Sit on the machine with your back against the pad and your feet secured. Place your hands on the handles or grip bars. Engage your core and slowly lean forward, allowing your back to round slightly. Pause for a moment at the bottom position, feeling a stretch in your lower back. Using your back muscles, slowly raise your torso back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina según el tamaño de tu cuerpo y tu rango de movimiento. Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies asegurados. Coloca las manos en las asas o en las barras de agarre. Activa el core e inclínate lentamente hacia adelante, permitiendo que la espalda se redondee ligeramente. Haz una pausa breve en la posición baja, sintiendo un estiramiento en la zona lumbar. Usando los músculos de la espalda, levanta lentamente el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/0573-rUXfn3R.jpg', 'videos/0573-rUXfn3R.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0574', 'lever bent over row', 'back', 'back', 'barbell', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Bend forward at the hips, keeping your back straight and chest up. Pull the barbell towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado. Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0574-X3cqyXz.jpg', 'videos/0574-X3cqyXz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3200', 'lever bent-over row with v-bar', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself facing the machine. Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent. Pull the v-bar towards your abdomen, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the weight back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate frente a la máquina. Sujeta la barra en V con un agarre prono, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Tira de la barra en V hacia el abdomen, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/3200-LuBEORI.jpg', 'videos/3200-LuBEORI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0575', 'lever bicep curl', 'upper arms', 'upper arms', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides. Exhale and curl the handles upward, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Sujeta las asas con un agarre supino, con las palmas hacia arriba, y mantén los codos cerca de los costados. Exhala y flexiona las asas hacia arriba, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0575-q6y3OhV.jpg', 'videos/0575-q6y3OhV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2289', 'lever calf press', 'lower legs', 'lower legs', 'leverage machine', 'Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad. Place your toes on the lever pad, with your heels hanging off the edge. Grasp the handles or side supports for stability. Push the lever pad down by extending your ankles, contracting your calf muscles. Pause for a moment at the bottom of the movement. Slowly return to the starting position by allowing your heels to rise back up. Repeat for the desired number of repetitions.', 'Ajusta el asiento de la máquina de palanca de modo que los hombros queden alineados con la almohadilla de la palanca. Coloca los dedos de los pies sobre la almohadilla de la palanca, con los talones colgando fuera del borde. Sujeta las asas o los soportes laterales para mayor estabilidad. Empuja la almohadilla de la palanca hacia abajo extendiendo los tobillos, contrayendo los músculos de las pantorrillas. Haz una pausa por un momento en la parte baja del movimiento. Vuelve lentamente a la posición inicial dejando que los talones se eleven de nuevo. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/2289-7B4F5nZ.jpg', 'videos/2289-7B4F5nZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0577', 'lever chest press', 'chest', 'chest', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back flat against the pad. Grasp the handles with an overhand grip and position your elbows at a 90-degree angle. Push the handles forward until your arms are fully extended, exhaling during the movement. Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla. Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados. Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento. Haz una pausa breve al final del movimiento, luego vuelve lentamente a la posición inicial, inhalando mientras lo haces. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0577-T0yTjgW.jpg', 'videos/0577-T0yTjgW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0576', 'lever chest press', 'chest', 'chest', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back flat against the pad. Grasp the handles with an overhand grip and position your elbows at a 90-degree angle. Push the handles forward until your arms are fully extended, exhaling during the movement. Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla. Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados. Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento. Haz una pausa breve al final del movimiento, luego vuelve lentamente a la posición inicial, inhalando mientras lo haces. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0576-DOoWcnA.jpg', 'videos/0576-DOoWcnA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0578', 'lever deadlift', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the seat height and foot platform to your desired position. Sit on the machine with your back against the pad and your feet flat on the foot platform. Grasp the handles or the sides of the seat for stability. Engage your glutes and hamstrings, and push through your heels to lift the weight up. Keep your back straight and avoid rounding your shoulders. Extend your hips fully at the top of the movement, squeezing your glutes. Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y la plataforma para los pies a la posición deseada. Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies planos sobre la plataforma para los pies. Sujeta las asas o los lados del asiento para mayor estabilidad. Activa los glúteos y los isquiotibiales, y empuja con los talones para levantar el peso. Mantén la espalda recta y evita redondear los hombros. Extiende por completo las caderas en la parte alta del movimiento, apretando los glúteos. Baja el peso de manera controlada, manteniendo la tensión en los glúteos y los isquiotibiales. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/0578-GUT8I22.jpg', 'videos/0578-GUT8I22.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1300', 'lever decline chest press', 'chest', 'chest', 'leverage machine', 'Adjust the seat height and backrest of the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart. Push the handles forward and away from your body until your arms are fully extended. Slowly lower the handles back towards your chest, keeping your elbows slightly bent. Pause for a moment at the bottom, then push the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros. Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos. Baja lentamente las asas de vuelta hacia el pecho, manteniendo los codos ligeramente flexionados. Haz una pausa breve en la parte baja, luego empuja las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1300-vsVoPHt.jpg', 'videos/1300-vsVoPHt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1253', 'lever donkey calf raise', 'lower legs', 'lower legs', 'leverage machine', 'Adjust the leverage machine to the appropriate height for your body. Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge. Place your hands on the handles or the support bars for stability. Engage your calves and lift your heels as high as possible, using the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de palanca a la altura adecuada para tu cuerpo. Colócate de frente a la máquina, con los dedos de los pies en la plataforma y los talones colgando fuera del borde. Coloca las manos en las asas o en las barras de soporte para mayor estabilidad. Activa las pantorrillas y levanta los talones tan alto como sea posible, usando la parte delantera de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1253-C9LuR4A.jpg', 'videos/1253-C9LuR4A.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0579', 'lever front pulldown', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back. Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Siéntate erguido con el pecho elevado y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar. Activa los dorsales y tira de las asas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/0579-7F1DVzn.jpg', 'videos/0579-7F1DVzn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0580', 'lever gripless shrug', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself on the leverage machine. Grasp the handles with your palms facing inwards and your arms fully extended. Keeping your back straight, exhale and elevate your shoulders as high as possible. Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina de palanca. Sujeta las asas con las palmas hacia adentro y los brazos completamente extendidos. Manteniendo la espalda recta, exhala y eleva los hombros tan alto como sea posible. Mantén la contracción por un momento breve, luego inhala y baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","forearms"]'::jsonb, 'traps', 'images/0580-f91FwXG.jpg', 'videos/0580-f91FwXG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1439', 'lever gripless shrug v. 2', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles or bars with an overhand grip, keeping your arms straight. Keeping your back straight, lift your shoulders up towards your ears as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Sujeta las asas o barras con un agarre prono, manteniendo los brazos rectos. Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","forearms"]'::jsonb, 'traps', 'images/1439-cbuFJrn.jpg', 'videos/1439-cbuFJrn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2288', 'lever gripper hands', 'lower arms', 'lower arms', 'leverage machine', 'Adjust the seat height and grip the handles of the leverage machine. Keep your back straight and your feet flat on the ground. Exhale and squeeze the handles, contracting your forearms. Hold the contraction for a second, then slowly release and return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y sujeta las asas de la máquina de palanca. Mantén la espalda recta y los pies planos en el suelo. Exhala y aprieta las asas, contrayendo los antebrazos. Mantén la contracción durante un segundo, luego suelta lentamente y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps"]'::jsonb, 'forearms', 'images/2288-mKwcrHn.jpg', 'videos/2288-mKwcrHn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1615', 'lever hammer grip preacher curl', 'upper arms', 'upper arms', 'leverage machine', 'Adjust the seat height and position yourself on the leverage machine. Place your upper arms on the preacher pad, ensuring your chest is pressed against it. Grasp the handles with a hammer grip (palms facing each other). Keeping your upper arms stationary, exhale and curl the handles towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina de palanca. Coloca los brazos superiores sobre la almohadilla de predicador, asegurándote de que el pecho quede apoyado contra ella. Sujeta las asas con agarre neutro (palmas una frente a la otra). Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1615-OAguZoG.jpg', 'videos/1615-OAguZoG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0581', 'lever high row', 'back', 'back', 'leverage machine', 'Adjust the seat height and foot platform to a comfortable position. Sit on the machine with your chest against the pad and your feet flat on the foot platform. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and engage your core. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y la plataforma para los pies a una posición cómoda. Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la plataforma para los pies. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y activa el core. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rear deltoids"]'::jsonb, 'upper back', 'images/0581-nZZZy9m.jpg', 'videos/0581-nZZZy9m.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2286', 'lever hip extension v. 2', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the machine to fit your body and sit on it with your back against the backrest. Place your feet on the footrests and grip the handles for stability. Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward. Pause for a moment at the top, then slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo. Coloca los pies en los apoyapiés y sujeta las asas para mayor estabilidad. Activa los glúteos y los isquiotibiales, luego empuja contra los apoyapiés para extender las caderas y levantar las piernas hacia atrás. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'glutes', 'images/2286-OPqShYN.jpg', 'videos/2286-OPqShYN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2611', 'lever horizontal one leg press', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate. Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate. Place your hands on the handles or sides of the machine for stability. Push the footplate away from your body by extending your leg, keeping your back against the backrest. Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ajusta el asiento de la máquina de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa para los pies. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies. Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad. Empuja la placa para los pies alejándola del cuerpo extendiendo la pierna, manteniendo la espalda apoyada en el respaldo. Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente la pierna para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/2611-9KU9TYF.jpg', 'videos/2611-9KU9TYF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1299', 'lever incline chest press', 'chest', 'chest', 'leverage machine', 'Adjust the seat and backrest of the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart. Push the handles forward and away from your body until your arms are fully extended. Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest. Repeat for the desired number of repetitions.', 'Ajusta el asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros. Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos. Haz una pausa breve, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1299-jHAnWmT.jpg', 'videos/1299-jHAnWmT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1479', 'lever incline chest press v. 2', 'chest', 'chest', 'leverage machine', 'Adjust the seat height and backrest angle on the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart. Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows. Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y el ángulo del respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros. Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1479-o17Jfkt.jpg', 'videos/1479-o17Jfkt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0582', 'lever kneeling leg curl', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the machine to fit your body and select the desired weight. Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads. Grasp the handles or the sides of the machine for stability. Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees. Pause for a moment at the top of the movement, squeezing your hamstrings. Inhale and slowly lower your legs back to the starting position, fully extending your knees. Repeat for the desired number of repetitions.', 'Ajusta la máquina a tu cuerpo y selecciona el peso deseado. Arrodíllate en la máquina mirando hacia abajo, con las rodillas apoyadas en la almohadilla y los pies asegurados bajo las almohadillas para los pies. Sujeta las asas o los lados de la máquina para mayor estabilidad. Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas. Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales. Inhala y baja lentamente las piernas de vuelta a la posición inicial, extendiendo por completo las rodillas. Repite el número de repeticiones deseado.', 'glutes', '["glutes"]'::jsonb, 'hamstrings', 'images/0582-nnmCTLN.jpg', 'videos/0582-nnmCTLN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0583', 'lever kneeling twist', 'waist', 'waist', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward. Grasp the handles or the sides of the machine for stability. Keeping your core engaged, twist your torso to one side as far as comfortably possible. Pause for a moment, then slowly return to the starting position. Repeat the twist to the opposite side. Continue alternating sides for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con las rodillas apoyadas en las almohadillas y la parte superior del cuerpo mirando hacia adelante. Sujeta las asas o los lados de la máquina para mayor estabilidad. Manteniendo el core activado, gira el torso hacia un lado tanto como sea cómodamente posible. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0583-sZOR9EV.jpg', 'videos/0583-sZOR9EV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0584', 'lever lateral raise', 'shoulders', 'shoulders', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with an overhand grip and keep your arms straight. Exhale and raise your arms out to the sides until they are parallel to the floor. Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Sujeta las asas con un agarre prono y mantén los brazos rectos. Exhala y levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa breve en lo alto, luego inhala y baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","upper back"]'::jsonb, 'delts', 'images/0584-dRTfGZT.jpg', 'videos/0584-dRTfGZT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0585', 'lever leg extension', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the seat height and backrest of the machine to fit your body. Sit on the machine with your back against the backrest and your feet on the footpad. Grasp the handles or sidebars for stability. Extend your legs forward by straightening your knees, lifting the weight. Pause for a moment at the top, then slowly lower the weight back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y el respaldo de la máquina a tu cuerpo. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la almohadilla para los pies. Sujeta las asas o las barras laterales para mayor estabilidad. Extiende las piernas hacia adelante enderezando las rodillas, levantando el peso. Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'quads', 'images/0585-my33uHU.jpg', 'videos/0585-my33uHU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0586', 'lever lying leg curl', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the machine to fit your body and select the desired weight. Lie face down on the machine with your legs straight and your heels against the padded lever. Grasp the handles or the sides of the machine for stability. Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad. Hold the contracted position for a brief pause as you squeeze your hamstrings. Inhale and slowly lower the lever back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina a tu cuerpo y selecciona el peso deseado. Túmbate boca abajo en la máquina con las piernas rectas y los talones contra la palanca acolchada. Sujeta las asas o los lados de la máquina para mayor estabilidad. Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba tanto como sea posible sin levantar las caderas de la almohadilla. Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales. Inhala y baja lentamente la palanca de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'calves', '["calves"]'::jsonb, 'hamstrings', 'images/0586-17lJ1kr.jpg', 'videos/0586-17lJ1kr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3195', 'lever lying two-one leg curl', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the machine to fit your body and sit on it with your back against the backrest. Place your legs on the lever pad, just above your ankles. Grasp the handles on the sides of the machine for support. Keeping your upper body still, exhale and curl your legs up towards your glutes. Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo. Coloca las piernas sobre la almohadilla de la palanca, justo encima de los tobillos. Sujeta las asas a los lados de la máquina para mayor apoyo. Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia los glúteos. Haz una pausa breve en lo alto, luego inhala y baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes"]'::jsonb, 'hamstrings', 'images/3195-UXpKJoq.jpg', 'videos/3195-UXpKJoq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0587', 'lever military press', 'shoulders', 'shoulders', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back against the backrest. Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart. Push the handles upward until your arms are fully extended, but do not lock your elbows. Pause for a moment at the top, then slowly lower the handles back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo. Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros. Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper chest"]'::jsonb, 'delts', 'images/0587-CggQhII.jpg', 'videos/0587-CggQhII.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0588', 'lever narrow grip seated row', 'back', 'back', 'leverage machine', 'Adjust the seat height and footrests to ensure proper form. Sit on the machine with your feet flat on the footrests and your knees slightly bent. Grasp the handles with a narrow grip, palms facing each other. Keep your back straight and lean slightly forward. Pull the handles towards your torso, squeezing your shoulder blades together. Pause for a moment at the peak of the movement. Slowly release the handles and return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y los apoyapiés para asegurar una postura correcta. Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia adelante. Tira de las asas hacia el torso, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente las asas y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0588-IGjKj1v.jpg', 'videos/0588-IGjKj1v.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0589', 'lever one arm bent over row', 'back', 'back', 'barbell', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip. Bend forward at the hips, keeping your back straight and your head up. Let the barbell hang in front of you with your arms fully extended. Pull the barbell up towards your chest, keeping your elbows close to your body. Squeeze your shoulder blades together at the top of the movement. Lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con agarre prono. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la cabeza erguida. Deja que la barra cuelgue frente a ti con los brazos completamente extendidos. Tira de la barra hacia el pecho, manteniendo los codos cerca del cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0589-Fhdtwf3.jpg', 'videos/0589-Fhdtwf3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1356', 'lever one arm lateral high row', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself facing the machine. Grasp the handle with one hand and keep your back straight. Pull the handle towards your body, keeping your elbow close to your side. Squeeze your back muscles at the top of the movement. Slowly release the handle back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate frente a la máquina. Sujeta el asa con una mano y mantén la espalda recta. Tira del asa hacia el cuerpo, manteniendo el codo cerca del costado. Aprieta los músculos de la espalda en la parte superior del movimiento. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/1356-OIFMAp1.jpg', 'videos/1356-OIFMAp1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1347', 'lever one arm lateral wide pulldown', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor. Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow. Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement. Slowly return the handle to the starting position, fully extending your arm. Repeat for the desired number of repetitions, then switch sides.', 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Sujeta el asa con un agarre prono y extiende el brazo por completo, manteniendo una ligera flexión en el codo. Tira del asa hacia abajo y a través del cuerpo en dirección a la cadera opuesta, apretando el dorsal en la parte baja del movimiento. Devuelve lentamente el asa a la posición inicial, extendiendo el brazo por completo. Repite el número de repeticiones deseado, luego cambia de lado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/1347-tTuZSDT.jpg', 'videos/1347-tTuZSDT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0590', 'lever one arm shoulder press', 'shoulders', 'shoulders', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the lever handle with one hand and position your elbow at a 90-degree angle. Press the lever upward until your arm is fully extended overhead. Pause for a moment at the top, then slowly lower the lever back down to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Sujeta el asa de la palanca con una mano y coloca el codo en un ángulo de 90 grados. Presiona la palanca hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0590-2KGnL6M.jpg', 'videos/0590-2KGnL6M.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0591', 'lever overhand triceps dip', 'upper arms', 'upper arms', 'leverage machine', 'Adjust the machine to the appropriate height and secure your body in position. Grasp the handles with an overhand grip and position your body so that your arms are fully extended. Lower your body by bending your elbows, keeping your upper arms close to your sides. Continue lowering until your upper arms are parallel to the floor. Pause for a moment, then push yourself back up to the starting position by extending your elbows. Repeat for the desired number of repetitions.', 'Ajusta la máquina a la altura adecuada y asegura tu cuerpo en posición. Sujeta las asas con un agarre prono y coloca el cuerpo de modo que los brazos queden completamente extendidos. Baja el cuerpo flexionando los codos, manteniendo los brazos superiores cerca de los costados. Continúa bajando hasta que los brazos superiores queden paralelos al suelo. Haz una pausa breve, luego empújate de vuelta hacia arriba a la posición inicial extendiendo los codos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0591-D5yqP2p.jpg', 'videos/0591-D5yqP2p.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0592', 'lever preacher curl', 'upper arms', 'upper arms', 'leverage machine', 'Adjust the seat height and position yourself on the leverage machine. Place your upper arms on the pad and grip the handles with an underhand grip. Keep your back straight and your elbows positioned on the pad. Exhale and curl your forearms towards your upper arms, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina de palanca. Coloca los brazos superiores en la almohadilla y sujeta las asas con un agarre supino. Mantén la espalda recta y los codos colocados sobre la almohadilla. Exhala y flexiona los antebrazos hacia los brazos superiores, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0592-b6hQYMb.jpg', 'videos/0592-b6hQYMb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1614', 'lever preacher curl v. 2', 'upper arms', 'upper arms', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support. Grasp the handles with an underhand grip, slightly wider than shoulder-width apart. Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale as you slowly lower the handles back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con los brazos superiores apoyados en la almohadilla y el pecho contra el soporte. Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros. Mantén los brazos superiores inmóviles y exhala mientras flexionas las asas hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala mientras bajas lentamente las asas de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1614-ye84CTU.jpg', 'videos/1614-ye84CTU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2285', 'lever pullover', 'back', 'back', 'leverage machine', 'Adjust the seat and handles of the leverage machine to a comfortable position. Sit on the machine with your back against the pad and grasp the handles with an overhand grip. Keep your arms slightly bent and your core engaged. Slowly pull the handles towards your chest, squeezing your lats. Pause for a moment at the peak contraction, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta el asiento y las asas de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en la almohadilla y sujeta las asas con un agarre prono. Mantén los brazos ligeramente flexionados y el core activado. Tira lentamente de las asas hacia el pecho, apretando los dorsales. Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'lats', 'images/2285-4U7iLb5.jpg', 'videos/2285-4U7iLb5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2736', 'lever reverse grip lateral pulldown', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back. Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar. Tira de las asas hacia el pecho, liderando con los codos y juntando los omóplatos. Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/2736-ky8FLU8.jpg', 'videos/2736-ky8FLU8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1616', 'lever reverse grip preacher curl', 'upper arms', 'upper arms', 'leverage machine', 'Adjust the seat height and position yourself on the leverage machine. Grasp the handles with an underhand grip, palms facing up. Rest your upper arms on the preacher pad, ensuring your elbows are fully extended. Keeping your upper arms stationary, exhale and curl the handles towards your shoulders. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the handles back to the starting position, fully extending your elbows. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina de palanca. Sujeta las asas con un agarre supino, con las palmas hacia arriba. Apoya los brazos superiores sobre la almohadilla de predicador, asegurándote de que los codos queden completamente extendidos. Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1616-kj3hy6W.jpg', 'videos/1616-kj3hy6W.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1348', 'lever reverse grip vertical row', 'back', 'back', 'leverage machine', 'Adjust the seat height and footplate position to ensure proper alignment. Sit on the machine with your chest against the pad and your feet flat on the footplate. Grasp the handles with an underhand grip, palms facing up. Keep your back straight and engage your core. Pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta. Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies. Sujeta las asas con un agarre supino, con las palmas hacia arriba. Mantén la espalda recta y activa el core. Tira de las asas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1348-ZqNOWQ6.jpg', 'videos/1348-ZqNOWQ6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0593', 'lever reverse hyperextension', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the leverage machine to fit your body and secure your feet in the foot pads. Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad. Cross your arms over your chest or place them behind your head. Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de palanca a tu cuerpo y asegura los pies en las almohadillas para los pies. Túmbate boca abajo en la máquina con la parte superior del cuerpo colgando fuera del borde y las caderas apoyadas en la almohadilla. Cruza los brazos sobre el pecho o colócalos detrás de la cabeza. Activa los glúteos y los isquiotibiales para levantar las piernas hacia arriba hasta que queden paralelas al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0593-Krmb3cB.jpg', 'videos/0593-Krmb3cB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1349', 'lever reverse t-bar row', 'back', 'back', 'leverage machine', 'Adjust the seat height and footplate position on the leverage machine. Sit on the machine with your chest against the pad and your feet flat on the footplate. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and engage your core. Pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y la posición de la placa para los pies en la máquina de palanca. Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y activa el core. Tira de las asas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1349-BgljGjd.jpg', 'videos/1349-BgljGjd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2315', 'lever rotary calf', 'lower legs', 'lower legs', 'leverage machine', 'Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate. Place your toes on the footplate, with your heels hanging off the edge. Grasp the handles or the sides of the machine for stability. Push through the balls of your feet, raising your heels as high as possible. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies. Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde. Sujeta las asas o los lados de la máquina para mayor estabilidad. Empuja con la parte delantera de los pies, elevando los talones tan alto como sea posible. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'soleus', '["soleus","ankle stabilizers"]'::jsonb, 'calves', 'images/2315-MrgP9L6.jpg', 'videos/2315-MrgP9L6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2335', 'lever seated calf press', 'lower legs', 'lower legs', 'leverage machine', 'Adjust the seat of the machine so that your shoulders are aligned with the lever pad. Place your toes on the lower portion of the platform and position your knees under the lever pad. Grasp the handles on the sides of the seat for stability. Press the lever pad down by extending your ankles, lifting your heels as high as possible. Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta el asiento de la máquina de modo que los hombros queden alineados con la almohadilla de la palanca. Coloca los dedos de los pies en la parte inferior de la plataforma y posiciona las rodillas debajo de la almohadilla de la palanca. Sujeta las asas a los lados del asiento para mayor estabilidad. Presiona la almohadilla de la palanca hacia abajo extendiendo los tobillos, elevando los talones tan alto como sea posible. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'soleus', '["soleus","hamstrings"]'::jsonb, 'calves', 'images/2335-Ie9UGty.jpg', 'videos/2335-Ie9UGty.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0594', 'lever seated calf raise', 'lower legs', 'lower legs', 'leverage machine', 'Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate. Place your toes on the footplate with your heels hanging off the edge. Grasp the handles or the sides of the seat for stability. Push through the balls of your feet to raise your heels as high as possible. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies. Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde. Sujeta las asas o los lados del asiento para mayor estabilidad. Empuja con la parte delantera de los pies para elevar los talones tan alto como sea posible. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'soleus', '["soleus","ankle stabilizers"]'::jsonb, 'calves', 'images/0594-bOOdeyc.jpg', 'videos/0594-bOOdeyc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1452', 'lever seated crunch', 'waist', 'waist', 'leverage machine', 'Sit on the leverage machine with your back against the pad and your feet flat on the floor. Grasp the handles or place your hands on the side pads for support. Engage your abs and slowly lean back, allowing the pad to move with you. Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees. Pause for a moment at the top, then slowly release and return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de palanca con la espalda apoyada en la almohadilla y los pies planos en el suelo. Sujeta las asas o coloca las manos sobre las almohadillas laterales para mayor apoyo. Activa el abdomen e inclínate lentamente hacia atrás, dejando que la almohadilla se mueva contigo. Cuando la parte superior del cuerpo esté en un ángulo de 45 grados, contrae el abdomen y haz un crunch hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa breve en lo alto, luego suelta lentamente y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/1452-Wgaz7pm.jpg', 'videos/1452-Wgaz7pm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0595', 'lever seated crunch (chest pad)', 'waist', 'waist', 'leverage machine', 'Adjust the seat height and chest pad position according to your comfort. Sit on the machine with your back against the chest pad and your feet flat on the floor. Grasp the handles or side bars for stability. Engage your abs and slowly lean back, allowing the chest pad to move with you. Pause for a moment at the maximum contraction, feeling the tension in your abs. Slowly return to the starting position by contracting your abs and pulling yourself back up. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y la posición de la almohadilla para el pecho según tu comodidad. Siéntate en la máquina con la espalda apoyada en la almohadilla para el pecho y los pies planos en el suelo. Sujeta las asas o las barras laterales para mayor estabilidad. Activa el abdomen y reclínate lentamente hacia atrás, permitiendo que el respaldo se mueva contigo. Haz una pausa en la contracción máxima, sintiendo la tensión en el abdomen. Vuelve lentamente a la posición inicial contrayendo el abdomen y tirando de tu cuerpo hacia arriba. Repite el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0595-ZnJHhMk.jpg', 'videos/0595-ZnJHhMk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3760', 'lever seated crunch v. 2', 'waist', 'waist', 'leverage machine', 'Sit on the leverage machine with your back against the pad and your feet secured under the footpads. Place your hands on the handles or the sides of the seat for support. Engage your abs and slowly crunch forward, bringing your chest towards your knees. Pause for a moment at the top of the movement, squeezing your abs. Slowly return to the starting position, allowing your back to round slightly. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sujetos bajo las almohadillas. Coloca las manos en las asas o en los lados del asiento para mayor apoyo. Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen. Vuelve lentamente a la posición inicial, dejando que tu espalda se redondee ligeramente. Repite el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/3760-eXFXCY0.jpg', 'videos/3760-eXFXCY0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1451', 'lever seated dip', 'upper arms', 'upper arms', 'leverage machine', 'Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle. Grasp the handles of the leverage machine with your palms facing down and your arms fully extended. Slowly lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento de modo que tus pies queden planos en el suelo y tus rodillas formen un ángulo de 90 grados. Agarra las asas de la máquina de palanca con las palmas hacia abajo y los brazos completamente extendidos. Baja lentamente el cuerpo flexionando los codos hasta que tus brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1451-BRImeP8.jpg', 'videos/1451-BRImeP8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0596', 'lever seated fly', 'chest', 'chest', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with a pronated grip and keep your elbows slightly bent. Exhale and push the handles forward, bringing them together in front of your chest. Pause for a moment, squeezing your chest muscles. Inhale and slowly return to the starting position, allowing your chest muscles to stretch. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Agarra las asas con un agarre pronado y mantén los codos ligeramente flexionados. Exhala y empuja las asas hacia adelante, juntándolas frente a tu pecho. Haz una pausa por un momento, contrayendo los músculos del pecho. Inhala y vuelve lentamente a la posición inicial, permitiendo que los músculos del pecho se estiren. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","trapezius"]'::jsonb, 'pectorals', 'images/0596-v3xmPAR.jpg', 'videos/0596-v3xmPAR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3759', 'lever seated good morning', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the seat height so that your hips are slightly higher than your knees. Sit on the machine with your back against the pad and your feet flat on the footrests. Grasp the handles or the sides of the seat for stability. Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground. Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento de modo que tus caderas queden un poco más altas que tus rodillas. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre los apoyapiés. Sujeta las asas o los lados del asiento para mayor estabilidad. Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas hasta que la parte superior de tu cuerpo quede paralela al suelo. Haz una pausa por un momento y luego vuelve lentamente a la posición inicial empujando con los glúteos y los isquiotibiales. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/3759-XsCcxCC.jpg', 'videos/3759-XsCcxCC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0597', 'lever seated hip abduction', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the seat height so that your knees are at a 90-degree angle. Sit on the machine with your back against the backrest and your feet on the footrests. Place your hands on the side handles for stability. Engage your abductors and slowly push your legs apart, away from the midline of your body. Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento de modo que tus rodillas formen un ángulo de 90 grados. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre los apoyapiés. Coloca las manos en las asas laterales para mayor estabilidad. Activa los abductores y empuja lentamente las piernas hacia afuera, alejándolas de la línea media del cuerpo. Haz una pausa al final del movimiento y luego junta lentamente las piernas de nuevo hasta la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'abductors', 'images/0597-CHpahtl.jpg', 'videos/0597-CHpahtl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0598', 'lever seated hip adduction', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back against the backrest. Place your feet on the footrests and grasp the handles for stability. Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs. Pause for a moment at the peak contraction, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo. Coloca los pies sobre los apoyapiés y agarra las asas para mayor estabilidad. Activa los aductores y junta lentamente las piernas, apretando la parte interna de los muslos. Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'adductors', 'images/0598-oHsrypV.jpg', 'videos/0598-oHsrypV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0599', 'lever seated leg curl', 'upper legs', 'upper legs', 'leverage machine', 'Adjust the machine to fit your body and sit on it with your back against the backrest. Place your lower legs under the padded lever, just above your ankles. Grasp the handles on the sides of the machine for support. Keeping your upper legs stationary, exhale and curl your legs up as far as possible. Hold the contracted position for a brief pause as you squeeze your hamstrings. Inhale and slowly lower the lever back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo. Coloca la parte baja de las piernas debajo de la palanca acolchada, justo por encima de los tobillos. Sujeta las asas a los lados de la máquina para mayor apoyo. Manteniendo la parte superior de las piernas inmóvil, exhala y flexiona las piernas hacia arriba todo lo que puedas. Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales. Inhala y baja lentamente la palanca de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'calves', '["calves"]'::jsonb, 'hamstrings', 'images/0599-Zg3XY7P.jpg', 'videos/0599-Zg3XY7P.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0600', 'lever seated leg raise crunch', 'waist', 'waist', 'leverage machine', 'Sit on the leverage machine with your back against the backrest and your feet on the footrests. Grasp the handles or sidebars for stability. Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time. Pause for a moment at the top, then slowly lower your legs and torso back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sobre los apoyapiés. Sujeta las asas o las barras laterales para mayor estabilidad. Activa el abdomen y eleva lentamente las piernas hacia el pecho, mientras curvas el torso hacia adelante al mismo tiempo. Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas y el torso a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0600-PQ2AtC3.jpg', 'videos/0600-PQ2AtC3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0602', 'lever seated reverse fly', 'shoulders', 'shoulders', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor. Grasp the handles with an overhand grip and keep your arms slightly bent. Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Agarra las asas con un agarre prono y mantén los brazos ligeramente flexionados. Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo. Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0602-myfUsKf.jpg', 'videos/0602-myfUsKf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0601', 'lever seated reverse fly (parallel grip)', 'shoulders', 'shoulders', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor. Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent. Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body. Pause for a moment at the peak contraction, then inhale and slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Agarra las asas con un agarre paralelo, con las palmas enfrentadas, y mantén los brazos ligeramente flexionados. Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo. Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0601-xiHiJcA.jpg', 'videos/0601-xiHiJcA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1350', 'lever seated row', 'back', 'back', 'leverage machine', 'Adjust the seat height and footrests to a comfortable position. Sit on the machine with your chest against the pad and your feet on the footrests. Grasp the handles with an overhand grip, shoulder-width apart. Keep your back straight and your core engaged. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement. Slowly release the handles and return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y los apoyapiés a una posición cómoda. Siéntate en la máquina con el pecho apoyado en la almohadilla y los pies sobre los apoyapiés. Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros. Mantén la espalda recta y el core activado. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente las asas y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1350-7I6LNUG.jpg', 'videos/1350-7I6LNUG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1385', 'lever seated squat calf raise on leg press machine', 'lower legs', 'lower legs', 'leverage machine', 'Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate. Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart. Place your toes and the balls of your feet on the footplate, keeping your heels off the edge. Release the safety handles and push the footplate away from you by extending your knees. Once your knees are fully extended, slowly lower your heels by flexing your calves. Pause for a moment at the bottom, then push the footplate back up by extending your calves. Repeat for the desired number of repetitions.', 'Ajusta el asiento de la máquina de prensa de piernas de modo que tus rodillas queden ligeramente flexionadas cuando los pies estén sobre la plataforma. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre la plataforma, separados a la altura de los hombros. Coloca los dedos y la planta de los pies sobre la plataforma, manteniendo los talones alejados del borde. Suelta las palancas de seguridad y empuja la plataforma alejándola de ti extendiendo las rodillas. Una vez que tus rodillas estén completamente extendidas, baja lentamente los talones flexionando las pantorrillas. Haz una pausa por un momento en la parte baja y luego empuja la plataforma de nuevo hacia arriba extendiendo las pantorrillas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","glutes"]'::jsonb, 'calves', 'images/1385-IeDEXTe.jpg', 'videos/1385-IeDEXTe.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0603', 'lever shoulder press', 'shoulders', 'shoulders', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back against the backrest. Grasp the handles with an overhand grip and position your hands at shoulder level. Push the handles upward until your arms are fully extended, but do not lock your elbows. Pause for a moment at the top, then slowly lower the handles back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo. Agarra las asas con un agarre prono y coloca las manos a la altura de los hombros. Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/0603-67n3r98.jpg', 'videos/0603-67n3r98.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0869', 'lever shoulder press v. 2', 'shoulders', 'shoulders', 'leverage machine', 'Adjust the seat height and backrest of the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart. Push the handles upward and forward until your arms are fully extended, but not locked. Pause for a moment at the top, then slowly lower the handles back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros. Empuja las asas hacia arriba y hacia adelante hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/0869-vqsbmL0.jpg', 'videos/0869-vqsbmL0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2318', 'lever shoulder press v. 3', 'shoulders', 'shoulders', 'leverage machine', 'Adjust the seat height and backrest of the leverage machine to a comfortable position. Sit on the machine with your back against the backrest and your feet flat on the floor. Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart. Push the handles upward and forward until your arms are fully extended, but not locked. Pause for a moment at the top, then slowly lower the handles back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra las asas de la máquina con un agarre prono, un poco más separadas que la anchura de los hombros. Empuja las asas hacia arriba y hacia adelante hasta que los brazos queden completamente extendidos, pero sin bloquear los codos. Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest"]'::jsonb, 'delts', 'images/2318-dNFYIU1.jpg', 'videos/2318-dNFYIU1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0604', 'lever shrug', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself on the leverage machine with your back against the pad. Grasp the handles with an overhand grip and keep your arms straight. Keeping your back straight, lift your shoulders up towards your ears as high as possible. Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina de palanca con la espalda apoyada en la almohadilla. Sujeta las asas con un agarre prono y mantén los brazos rectos. Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'traps', 'images/0604-ZZKbeMw.jpg', 'videos/0604-ZZKbeMw.gif');
